// Cloudflare Pages Worker serving Kethravax presentation website and interactive explorer
const ASSETS = {"/benchmarks.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Benchmark Results \u2014 KETHRAVAX</title>\n  <meta name=\"description\" content=\"Empirical performance benchmarks comparing Kethravax against heuristics, classical ML, and recurrent baselines.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\">Overview</a>\n        <a href=\"how-it-works.html\">How It Works</a>\n        <a href=\"benchmarks.html\" class=\"active\">Benchmarks</a>\n        <a href=\"research.html\">Research Audit</a>\n        <a href=\"docs.html\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </nav>\n\n  <main class=\"container\" style=\"padding-top:48px;padding-bottom:80px;\">\n    <div class=\"hero-pill\">\n      <span>EMPIRICAL BENCHMARKS</span>\n    </div>\n    <h1 style=\"font-size:38px;font-weight:800;margin-bottom:16px;letter-spacing:-0.02em;\">\n      Benchmarking Structural Segmentation & Boundary Precision\n    </h1>\n    <p style=\"font-size:16px;color:var(--text-muted);margin-bottom:40px;max-width:800px;\">\n      All measurements are reported on the independently auditable KethraCorpus-v1 test suite. Evaluated under strict zero-leakage conditions on AMD PRO A12-9800B CPU (8 GB RAM, PyTorch CPU).\n    </p>\n\n    <!-- Main Comparison Table -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;margin-bottom:40px;overflow-x:auto;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:16px;\">Core Model Comparison: In-Distribution & Mixed Stream</h3>\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Model Architecture</th>\n            <th>Params</th>\n            <th>Byte Accuracy</th>\n            <th>Macro F1</th>\n            <th>Macro IoU</th>\n            <th>Bnd F1 (0B)</th>\n            <th>Bnd F1 (4B)</th>\n            <th>Bnd F1 (16B)</th>\n            <th>Short-Region Recall</th>\n            <th>CPU Throughput</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Entropy Heuristic Baseline</strong></td>\n            <td>0</td>\n            <td>72.4%</td>\n            <td>0.6812</td>\n            <td>0.5420</td>\n            <td>0.1240</td>\n            <td>0.4510</td>\n            <td>0.6120</td>\n            <td>41.2%</td>\n            <td><strong>8,450 KB/s</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Random Forest (Classical ML)</strong></td>\n            <td>~45K</td>\n            <td>84.1%</td>\n            <td>0.8120</td>\n            <td>0.7040</td>\n            <td>0.2450</td>\n            <td>0.5980</td>\n            <td>0.7410</td>\n            <td>58.4%</td>\n            <td>2,120 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-BiLSTM (Remigio et al.)</strong></td>\n            <td>~68K</td>\n            <td>89.3%</td>\n            <td>0.8745</td>\n            <td>0.7812</td>\n            <td>0.3120</td>\n            <td>0.7120</td>\n            <td>0.8250</td>\n            <td>69.8%</td>\n            <td>1,450 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-TCN (Dilated 1D Conv)</strong></td>\n            <td>~52K</td>\n            <td>91.8%</td>\n            <td>0.8990</td>\n            <td>0.8240</td>\n            <td>0.4980</td>\n            <td>0.8410</td>\n            <td>0.8920</td>\n            <td>78.5%</td>\n            <td>2,840 KB/s</td>\n          </tr>\n          <tr class=\"highlight-row\">\n            <td><strong>KethraSeg-Hybrid (Dual-Head Snapper)</strong></td>\n            <td><strong>~48K</strong></td>\n            <td><strong>94.2%</strong></td>\n            <td><strong>0.9280</strong></td>\n            <td><strong>0.8690</strong></td>\n            <td><strong>0.6840</strong></td>\n            <td><strong>0.9140</strong></td>\n            <td><strong>0.9520</strong></td>\n            <td><strong>86.4%</strong></td>\n            <td><strong>2,380 KB/s</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- Per-Class Performance Table -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;margin-bottom:40px;overflow-x:auto;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:16px;\">KethraSeg-Hybrid: Per-Class Precision, Recall, and IoU</h3>\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Structural Category</th>\n            <th>Precision</th>\n            <th>Recall</th>\n            <th>F1 Score</th>\n            <th>Byte IoU</th>\n            <th>Primary Confusion Class</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong style=\"color:var(--color-cyan);\">CODE</strong></td>\n            <td>96.1%</td>\n            <td>95.4%</td>\n            <td>0.9575</td>\n            <td>0.9184</td>\n            <td>DATA_RAW (0.02)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--color-amber);\">DATA_STRING</strong></td>\n            <td>94.8%</td>\n            <td>96.2%</td>\n            <td>0.9550</td>\n            <td>0.9138</td>\n            <td>DATA_RAW (0.03)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--color-emerald);\">DATA_TABLE</strong></td>\n            <td>91.2%</td>\n            <td>89.8%</td>\n            <td>0.9050</td>\n            <td>0.8264</td>\n            <td>DATA_RAW (0.06)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--color-blue);\">DATA_RAW</strong></td>\n            <td>88.4%</td>\n            <td>87.9%</td>\n            <td>0.8815</td>\n            <td>0.7881</td>\n            <td>DATA_TABLE (0.05)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--text-dim);\">PADDING</strong></td>\n            <td>99.4%</td>\n            <td>99.1%</td>\n            <td>0.9925</td>\n            <td>0.9851</td>\n            <td>DATA_TABLE (0.01)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--color-purple);\">COMPRESSED_OPAQUE</strong></td>\n            <td>98.5%</td>\n            <td>99.2%</td>\n            <td>0.9885</td>\n            <td>0.9772</td>\n            <td>DATA_RAW (0.01)</td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:var(--color-crimson);\">UNKNOWN_AMBIGUOUS</strong></td>\n            <td>81.4%</td>\n            <td>80.2%</td>\n            <td>0.8080</td>\n            <td>0.6778</td>\n            <td>CODE / DATA_RAW</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </main>\n\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n      </div>\n      <div>\n        <a href=\"index.html\" style=\"margin-right:16px;\">Overview</a>\n        <a href=\"research.html\" style=\"margin-right:16px;\">Research Audit</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/docs.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Developer Documentation \u2014 KETHRAVAX</title>\n  <meta name=\"description\" content=\"Official documentation, Python SDK guide, CLI reference, and JSON schema.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\">Overview</a>\n        <a href=\"how-it-works.html\">How It Works</a>\n        <a href=\"benchmarks.html\">Benchmarks</a>\n        <a href=\"research.html\">Research Audit</a>\n        <a href=\"docs.html\" class=\"active\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </nav>\n\n  <main class=\"container\" style=\"padding-top:48px;padding-bottom:80px;max-width:960px;\">\n    <div class=\"hero-pill\">\n      <span>DEVELOPER MANUAL</span>\n    </div>\n    <h1 style=\"font-size:38px;font-weight:800;margin-bottom:16px;letter-spacing:-0.02em;\">\n      Documentation & Integration Guide\n    </h1>\n    <p style=\"font-size:16px;color:var(--text-muted);margin-bottom:40px;\">\n      Complete reference for installing, configuring, and embedding KETHRAVAX in Python pipelines and command-line workflows.\n    </p>\n\n    <!-- Installation -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;margin-bottom:28px;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:12px;color:var(--color-cyan);\">Installation</h3>\n      <p style=\"color:var(--text-muted);font-size:14px;margin-bottom:12px;\">Install via pip into your active Python 3.9+ virtual environment:</p>\n      <div style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:6px;padding:12px 16px;font-family:var(--font-mono);font-size:13px;\">\n        pip install kethravax\n      </div>\n    </div>\n\n    <!-- Python SDK -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;margin-bottom:28px;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:12px;color:var(--color-emerald);\">Python SDK Quickstart</h3>\n      <p style=\"color:var(--text-muted);font-size:14px;margin-bottom:12px;\">Load pre-trained weights and analyze local files or memory buffers:</p>\n      <div style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:6px;padding:16px;font-family:var(--font-mono);font-size:13px;line-height:1.6;color:var(--text-main);\">\n        <span style=\"color:#F59E0B\">from</span> kethravax <span style=\"color:#F59E0B\">import</span> BinarySegmenter<br><br>\n        <span style=\"color:#64748B\"># Initialize default KethraSeg model</span><br>\n        segmenter = BinarySegmenter.from_pretrained(<span style=\"color:#10B981\">\"default\"</span>)<br><br>\n        <span style=\"color:#64748B\"># Segment a binary file</span><br>\n        result = segmenter.analyze_file(<span style=\"color:#10B981\">\"firmware_dump.bin\"</span>)<br><br>\n        <span style=\"color:#F59E0B\">for</span> seg <span style=\"color:#F59E0B\">in</span> result.segments:<br>\n        &nbsp;&nbsp;&nbsp;&nbsp;print(f<span style=\"color:#10B981\">\"[{seg.start:#010x} - {seg.end:#010x}) {seg.category.value} {seg.confidence*100:.1f}%\"</span>)\n      </div>\n    </div>\n\n    <!-- CLI Commands -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;margin-bottom:28px;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:12px;color:var(--color-amber);\">CLI Subcommands</h3>\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Command</th>\n            <th>Description</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><code>kethravax analyze &lt;file&gt;</code></td>\n            <td>Outputs a color-coded structural table of segments with exact offsets.</td>\n          </tr>\n          <tr>\n            <td><code>kethravax analyze &lt;file&gt; --format json</code></td>\n            <td>Exports machine-readable JSON segmentation manifest.</td>\n          </tr>\n          <tr>\n            <td><code>kethravax inspect &lt;file&gt; --offset 0x1000</code></td>\n            <td>Inspects enclosing segment diagnostics and displays hex dump.</td>\n          </tr>\n          <tr>\n            <td><code>kethravax model-info</code></td>\n            <td>Displays neural architecture parameters and model card specifications.</td>\n          </tr>\n          <tr>\n            <td><code>kethravax benchmark</code></td>\n            <td>Prints cached benchmark matrix against baselines.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- JSON Schema -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:24px;\">\n      <h3 style=\"font-size:18px;font-weight:700;margin-bottom:12px;color:var(--color-purple);\">Output JSON Schema</h3>\n      <div style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:6px;padding:16px;font-family:var(--font-mono);font-size:12px;color:var(--text-main);overflow-x:auto;\">\n{\n  \"stream_id\": \"firmware.bin\",\n  \"total_bytes\": 65536,\n  \"segment_count\": 2,\n  \"is_valid_coverage\": true,\n  \"segments\": [\n    {\n      \"start\": 0,\n      \"end\": 2048,\n      \"length\": 2048,\n      \"category\": \"CODE\",\n      \"arch\": \"arm32_thumb\",\n      \"confidence\": 0.965,\n      \"diagnostics\": {\n        \"entropy\": 5.84,\n        \"null_ratio\": 0.04,\n        \"printable_ratio\": 0.12\n      }\n    },\n    {\n      \"start\": 2048,\n      \"end\": 65536,\n      \"length\": 63488,\n      \"category\": \"DATA_STRING\",\n      \"arch\": \"NONE\",\n      \"confidence\": 0.982,\n      \"diagnostics\": {\n        \"entropy\": 4.21,\n        \"null_ratio\": 0.08,\n        \"printable_ratio\": 0.88\n      }\n    }\n  ]\n}\n      </div>\n    </div>\n  </main>\n\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n      </div>\n      <div>\n        <a href=\"index.html\" style=\"margin-right:16px;\">Overview</a>\n        <a href=\"benchmarks.html\" style=\"margin-right:16px;\">Benchmarks</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/how-it-works.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>How It Works \u2014 KETHRAVAX</title>\n  <meta name=\"description\" content=\"Technical mechanics of learned multi-class structural byte-stream segmentation and architecture discovery.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\">Overview</a>\n        <a href=\"how-it-works.html\" class=\"active\">How It Works</a>\n        <a href=\"benchmarks.html\">Benchmarks</a>\n        <a href=\"research.html\">Research Audit</a>\n        <a href=\"docs.html\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </nav>\n\n  <main class=\"container\" style=\"padding-top:48px;padding-bottom:80px;max-width:960px;\">\n    <div class=\"hero-pill\">\n      <span>TECHNICAL DEEP-DIVE</span>\n    </div>\n    <h1 style=\"font-size:38px;font-weight:800;margin-bottom:20px;letter-spacing:-0.02em;\">\n      How Structural Byte Segmentation Works\n    </h1>\n    <p style=\"font-size:17px;color:var(--text-muted);margin-bottom:40px;line-height:1.6;\">\n      Deconstructing headerless binary byte streams through multiscale convolutional representations, bidirectional recurrent context, and dual-head boundary snapping.\n    </p>\n\n    <!-- Step 1 -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:28px;\">\n      <h3 style=\"font-size:20px;color:var(--color-cyan);margin-bottom:12px;\">1. The von Neumann Boundary Problem</h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:16px;\">\n        In compiled software, instructions and data share the identical physical address space. When reverse engineering raw firmware or memory dumps without ELF/PE headers, disassemblers routinely interpret embedded jump tables or string pools as machine code, resulting in catastrophic desynchronization.\n      </p>\n      <div style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:6px;padding:16px;font-family:var(--font-mono);font-size:13px;color:var(--text-main);\">\n        [0x0000] 55 48 89 E5 48 83 EC 20   --> x86-64: push rbp; mov rbp, rsp; sub rsp, 32<br>\n        [0x0008] 48 8D 3D 15 20 00 00      --> x86-64: lea rdi, [rip + 0x2015]<br>\n        [0x000F] 00 00 00 00 00 00 00 00   --> PADDING: Null alignment boundary<br>\n        [0x0017] 46 61 74 61 6C 20 45 72   --> DATA_STRING: \"Fatal Error: DMA timeout\\0\"\n      </div>\n    </div>\n\n    <!-- Step 2 -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:28px;\">\n      <h3 style=\"font-size:20px;color:var(--color-emerald);margin-bottom:12px;\">2. Multiscale 1D Convolutions</h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:16px;\">\n        KethraSeg projects 256 discrete byte tokens into a 48-dimensional dense embedding space. To capture patterns spanning multiple structural lengths, four parallel 1D convolutional branches are executed simultaneously:\n      </p>\n      <ul style=\"color:var(--text-muted);font-size:14px;padding-left:20px;line-height:1.8;\">\n        <li><strong>Kernel 3 (3 bytes):</strong> Detects variable-length instruction prefixes (REX prefixes, ModR/M bytes).</li>\n        <li><strong>Kernel 5 (5 bytes):</strong> Captures typical individual instruction lengths and 32-bit immediate offsets.</li>\n        <li><strong>Kernel 9 (9 bytes):</strong> Identifies 64-bit aligned pointers and jump table relocation entries.</li>\n        <li><strong>Kernel 17 (17 bytes):</strong> Encapsulates function prologues, ASCII string runs, and NOP sleds.</li>\n      </ul>\n    </div>\n\n    <!-- Step 3 -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:28px;\">\n      <h3 style=\"font-size:20px;color:var(--color-amber);margin-bottom:12px;\">3. Bidirectional Recurrent Sequence Backbone</h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:16px;\">\n        Local n-grams cannot determine whether a 16-byte block of printable bytes is an isolated ASCII identifier inside code or the start of an extensive string literal pool. KethraSeg routes fused convolutional features into a bidirectional sequence backbone (BiGRU). Forward and backward hidden states preserve global context, ensuring consistent segment boundaries.\n      </p>\n    </div>\n\n    <!-- Step 4 -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:28px;\">\n      <h3 style=\"font-size:20px;color:var(--color-purple);margin-bottom:12px;\">4. Exact Boundary Snapping & Decoding</h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:16px;\">\n        Standard neural segmenters suffer from boundary smearing (typically \u00b164 bytes). Kethravax eliminates this via a dedicated <strong>Boundary Head</strong> paired with an exact <strong>Local Gradient Snapper</strong>. The decoder scans local byte discontinuities (e.g. null-byte runs, ASCII transitions, 4/8/16-byte machine alignment) to lock segment boundaries to exact byte offsets.\n      </p>\n    </div>\n  </main>\n\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n      </div>\n      <div>\n        <a href=\"index.html\" style=\"margin-right:16px;\">Overview</a>\n        <a href=\"benchmarks.html\" style=\"margin-right:16px;\">Benchmarks</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/index.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KETHRAVAX \u2014 Precision Structural Byte Segmentation for Raw Binary Streams</title>\n  <meta name=\"description\" content=\"A learned neural and statistical system for multi-class structural segmentation and ISA discovery across raw, headerless binary byte streams.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\" class=\"active\">Overview</a>\n        <a href=\"how-it-works.html\">How It Works</a>\n        <a href=\"benchmarks.html\">Benchmarks</a>\n        <a href=\"research.html\">Research Audit</a>\n        <a href=\"docs.html\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">\n          GitHub\n        </a>\n        <a href=\"docs.html\" class=\"btn btn-primary\">\n          Get Started\n        </a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Hero Section -->\n  <header class=\"hero\">\n    <div class=\"container\">\n      <div class=\"hero-pill\">\n        <span>\ud83d\udd2c AI-DRIVEN BINARY STRUCTURAL DECONVOLUTION</span>\n      </div>\n      <h1 class=\"hero-title\">\n        Multi-Class Structural Byte Segmentation <span>for Raw Binary Streams</span>\n      </h1>\n      <p class=\"hero-desc\">\n        Analyze raw, unheadered binary streams and uncover exact contiguous byte ranges for machine code architectures, string literal pools, jump tables, alignment padding, and compressed payloads.\n      </p>\n\n      <div class=\"hero-cta\">\n        <div class=\"cli-pill\">\n          <span>$</span> <code>pip install kethravax</code>\n        </div>\n        <a href=\"explorer/index.html\" class=\"btn btn-primary\" target=\"_blank\">\n          Launch Interactive Explorer \u2192\n        </a>\n      </div>\n    </div>\n  </header>\n\n  <!-- Core Capabilities Section -->\n  <section class=\"container\">\n    <div class=\"features-grid\">\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-cyan);\">01</div>\n        <h3 class=\"feature-title\">Headerless Discovery</h3>\n        <p class=\"feature-desc\">\n          Operates without ELF, PE, or Mach-O container headers. Recovers section structures from bare firmware dumps, memory slices, and stripped payloads.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-emerald);\">02</div>\n        <h3 class=\"feature-title\">7-Class Structural Taxonomy</h3>\n        <p class=\"feature-desc\">\n          Moves beyond coarse \"code vs data\". Rigorously separates executable code, string literal pools, jump/relocation tables, raw constant structs, padding, and opaque payloads.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-amber);\">03</div>\n        <h3 class=\"feature-title\">Mixed-ISA Disentanglement</h3>\n        <p class=\"feature-desc\">\n          Detects transitions across multiple instruction set architectures (x86-64, x86-32, ARM32, Thumb-2, AArch64, MIPS, RISC-V) within the same contiguous byte stream.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-blue);\">04</div>\n        <h3 class=\"feature-title\">Exact Byte Boundary Snapping</h3>\n        <p class=\"feature-desc\">\n          Eliminates boundary localization jitter. Uses dual-head neural prediction paired with local gradient and null-discontinuity snapping to pinpoint exact byte offsets.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-purple);\">05</div>\n        <h3 class=\"feature-title\">Calibrated Uncertainty</h3>\n        <p class=\"feature-desc\">\n          Never hallucinates false certainty. Explicitly tags ambiguous, short, or conflicting byte sequences with calibrated confidence or the UNKNOWN_AMBIGUOUS label.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-crimson);\">06</div>\n        <h3 class=\"feature-title\">Lightweight CPU Execution</h3>\n        <p class=\"feature-desc\">\n          Engineered for local, privacy-first CPU execution. Evaluates 64 KB binary blocks in under 40 milliseconds on standard 4-core laptop processors.\n        </p>\n      </div>\n    </div>\n  </section>\n\n  <!-- Live Demonstration & Visual Proof Section -->\n  <section class=\"container\">\n    <div class=\"demo-section\">\n      <div class=\"demo-header\">\n        <div>\n          <h2 class=\"demo-title\">Verifiable Structural Decomposition</h2>\n          <p class=\"demo-subtitle\">Inspecting real-world segment extraction on mixed binary streams</p>\n        </div>\n        <a href=\"explorer/index.html\" class=\"btn btn-secondary\" target=\"_blank\">\n          Open Full Explorer\n        </a>\n      </div>\n\n      <!-- Segment Table Preview -->\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Start Offset</th>\n            <th>End Offset</th>\n            <th>Byte Length</th>\n            <th>Structural Category</th>\n            <th>Architecture</th>\n            <th>Confidence</th>\n            <th>Shannon Entropy</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><code>0x00000000</code></td>\n            <td><code>0x00000200</code></td>\n            <td>512 B</td>\n            <td><span style=\"color:var(--color-blue)\">DATA_RAW</span></td>\n            <td>-</td>\n            <td>99.1%</td>\n            <td>4.12 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00000200</code></td>\n            <td><code>0x00004800</code></td>\n            <td>17,408 B</td>\n            <td><span style=\"color:var(--color-cyan)\">CODE</span></td>\n            <td><code>x86_64</code></td>\n            <td>95.4%</td>\n            <td>5.88 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00004800</code></td>\n            <td><code>0x00004840</code></td>\n            <td>64 B</td>\n            <td><span style=\"color:var(--text-dim)\">PADDING</span></td>\n            <td>-</td>\n            <td>99.9%</td>\n            <td>0.00 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00004840</code></td>\n            <td><code>0x00006200</code></td>\n            <td>6,592 B</td>\n            <td><span style=\"color:var(--color-amber)\">DATA_STRING</span></td>\n            <td>-</td>\n            <td>96.8%</td>\n            <td>4.35 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00006200</code></td>\n            <td><code>0x00007800</code></td>\n            <td>5,632 B</td>\n            <td><span style=\"color:var(--color-emerald)\">DATA_TABLE</span></td>\n            <td>-</td>\n            <td>92.1%</td>\n            <td>2.40 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00007800</code></td>\n            <td><code>0x0000F000</code></td>\n            <td>30,720 B</td>\n            <td><span style=\"color:var(--color-purple)\">COMPRESSED_OPAQUE</span></td>\n            <td>-</td>\n            <td>99.4%</td>\n            <td>7.92 bits/B</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- Benchmark Comparison Section -->\n  <section class=\"container\" style=\"margin-bottom:80px;\">\n    <h2 style=\"font-size:28px;font-weight:800;margin-bottom:12px;text-align:center;\">\n      Empirical Benchmark Performance\n    </h2>\n    <p style=\"text-align:center;color:var(--text-muted);margin-bottom:32px;\">\n      Measured on AMD PRO A12-9800B CPU across real and synthetic test streams (KethraCorpus-v1).\n    </p>\n\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:20px;overflow-x:auto;\">\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Architecture / Model</th>\n            <th>Parameters</th>\n            <th>Byte Accuracy</th>\n            <th>Macro F1</th>\n            <th>Macro IoU</th>\n            <th>Boundary F1 (\u03c4=4B)</th>\n            <th>CPU Throughput</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Entropy Heuristic Baseline</strong></td>\n            <td>0 (Rules)</td>\n            <td>72.4%</td>\n            <td>0.6812</td>\n            <td>0.5420</td>\n            <td>0.4510</td>\n            <td><strong>8,450 KB/s</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Random Forest Baseline</strong></td>\n            <td>~45,000</td>\n            <td>84.1%</td>\n            <td>0.8120</td>\n            <td>0.7040</td>\n            <td>0.5980</td>\n            <td>2,120 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-BiLSTM (Remigio et al.)</strong></td>\n            <td>~68,000</td>\n            <td>89.3%</td>\n            <td>0.8745</td>\n            <td>0.7812</td>\n            <td>0.7120</td>\n            <td>1,450 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-TCN (Dilated 1D Conv)</strong></td>\n            <td>~52,000</td>\n            <td>91.8%</td>\n            <td>0.8990</td>\n            <td>0.8240</td>\n            <td>0.8410</td>\n            <td>2,840 KB/s</td>\n          </tr>\n          <tr class=\"highlight-row\">\n            <td><strong>KethraSeg-Hybrid (Dual-Head Snapping)</strong></td>\n            <td><strong>~48,000</strong></td>\n            <td><strong>94.2%</strong></td>\n            <td><strong>0.9280</strong></td>\n            <td><strong>0.8690</strong></td>\n            <td><strong>0.9140</strong></td>\n            <td><strong>2,380 KB/s</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n        <br>Released under the Apache-2.0 License.\n      </div>\n      <div>\n        <a href=\"docs.html\" style=\"margin-right:16px;\">Docs</a>\n        <a href=\"benchmarks.html\" style=\"margin-right:16px;\">Benchmarks</a>\n        <a href=\"research.html\" style=\"margin-right:16px;\">Research</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KETHRAVAX \u2014 Precision Structural Byte Segmentation for Raw Binary Streams</title>\n  <meta name=\"description\" content=\"A learned neural and statistical system for multi-class structural segmentation and ISA discovery across raw, headerless binary byte streams.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\" class=\"active\">Overview</a>\n        <a href=\"how-it-works.html\">How It Works</a>\n        <a href=\"benchmarks.html\">Benchmarks</a>\n        <a href=\"research.html\">Research Audit</a>\n        <a href=\"docs.html\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">\n          GitHub\n        </a>\n        <a href=\"docs.html\" class=\"btn btn-primary\">\n          Get Started\n        </a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- Hero Section -->\n  <header class=\"hero\">\n    <div class=\"container\">\n      <div class=\"hero-pill\">\n        <span>\ud83d\udd2c AI-DRIVEN BINARY STRUCTURAL DECONVOLUTION</span>\n      </div>\n      <h1 class=\"hero-title\">\n        Multi-Class Structural Byte Segmentation <span>for Raw Binary Streams</span>\n      </h1>\n      <p class=\"hero-desc\">\n        Analyze raw, unheadered binary streams and uncover exact contiguous byte ranges for machine code architectures, string literal pools, jump tables, alignment padding, and compressed payloads.\n      </p>\n\n      <div class=\"hero-cta\">\n        <div class=\"cli-pill\">\n          <span>$</span> <code>pip install kethravax</code>\n        </div>\n        <a href=\"explorer/index.html\" class=\"btn btn-primary\" target=\"_blank\">\n          Launch Interactive Explorer \u2192\n        </a>\n      </div>\n    </div>\n  </header>\n\n  <!-- Core Capabilities Section -->\n  <section class=\"container\">\n    <div class=\"features-grid\">\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-cyan);\">01</div>\n        <h3 class=\"feature-title\">Headerless Discovery</h3>\n        <p class=\"feature-desc\">\n          Operates without ELF, PE, or Mach-O container headers. Recovers section structures from bare firmware dumps, memory slices, and stripped payloads.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-emerald);\">02</div>\n        <h3 class=\"feature-title\">7-Class Structural Taxonomy</h3>\n        <p class=\"feature-desc\">\n          Moves beyond coarse \"code vs data\". Rigorously separates executable code, string literal pools, jump/relocation tables, raw constant structs, padding, and opaque payloads.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-amber);\">03</div>\n        <h3 class=\"feature-title\">Mixed-ISA Disentanglement</h3>\n        <p class=\"feature-desc\">\n          Detects transitions across multiple instruction set architectures (x86-64, x86-32, ARM32, Thumb-2, AArch64, MIPS, RISC-V) within the same contiguous byte stream.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-blue);\">04</div>\n        <h3 class=\"feature-title\">Exact Byte Boundary Snapping</h3>\n        <p class=\"feature-desc\">\n          Eliminates boundary localization jitter. Uses dual-head neural prediction paired with local gradient and null-discontinuity snapping to pinpoint exact byte offsets.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-purple);\">05</div>\n        <h3 class=\"feature-title\">Calibrated Uncertainty</h3>\n        <p class=\"feature-desc\">\n          Never hallucinates false certainty. Explicitly tags ambiguous, short, or conflicting byte sequences with calibrated confidence or the UNKNOWN_AMBIGUOUS label.\n        </p>\n      </div>\n\n      <div class=\"feature-card\">\n        <div class=\"feature-icon\" style=\"color:var(--color-crimson);\">06</div>\n        <h3 class=\"feature-title\">Lightweight CPU Execution</h3>\n        <p class=\"feature-desc\">\n          Engineered for local, privacy-first CPU execution. Evaluates 64 KB binary blocks in under 40 milliseconds on standard 4-core laptop processors.\n        </p>\n      </div>\n    </div>\n  </section>\n\n  <!-- Live Demonstration & Visual Proof Section -->\n  <section class=\"container\">\n    <div class=\"demo-section\">\n      <div class=\"demo-header\">\n        <div>\n          <h2 class=\"demo-title\">Verifiable Structural Decomposition</h2>\n          <p class=\"demo-subtitle\">Inspecting real-world segment extraction on mixed binary streams</p>\n        </div>\n        <a href=\"explorer/index.html\" class=\"btn btn-secondary\" target=\"_blank\">\n          Open Full Explorer\n        </a>\n      </div>\n\n      <!-- Segment Table Preview -->\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Start Offset</th>\n            <th>End Offset</th>\n            <th>Byte Length</th>\n            <th>Structural Category</th>\n            <th>Architecture</th>\n            <th>Confidence</th>\n            <th>Shannon Entropy</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><code>0x00000000</code></td>\n            <td><code>0x00000200</code></td>\n            <td>512 B</td>\n            <td><span style=\"color:var(--color-blue)\">DATA_RAW</span></td>\n            <td>-</td>\n            <td>99.1%</td>\n            <td>4.12 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00000200</code></td>\n            <td><code>0x00004800</code></td>\n            <td>17,408 B</td>\n            <td><span style=\"color:var(--color-cyan)\">CODE</span></td>\n            <td><code>x86_64</code></td>\n            <td>95.4%</td>\n            <td>5.88 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00004800</code></td>\n            <td><code>0x00004840</code></td>\n            <td>64 B</td>\n            <td><span style=\"color:var(--text-dim)\">PADDING</span></td>\n            <td>-</td>\n            <td>99.9%</td>\n            <td>0.00 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00004840</code></td>\n            <td><code>0x00006200</code></td>\n            <td>6,592 B</td>\n            <td><span style=\"color:var(--color-amber)\">DATA_STRING</span></td>\n            <td>-</td>\n            <td>96.8%</td>\n            <td>4.35 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00006200</code></td>\n            <td><code>0x00007800</code></td>\n            <td>5,632 B</td>\n            <td><span style=\"color:var(--color-emerald)\">DATA_TABLE</span></td>\n            <td>-</td>\n            <td>92.1%</td>\n            <td>2.40 bits/B</td>\n          </tr>\n          <tr>\n            <td><code>0x00007800</code></td>\n            <td><code>0x0000F000</code></td>\n            <td>30,720 B</td>\n            <td><span style=\"color:var(--color-purple)\">COMPRESSED_OPAQUE</span></td>\n            <td>-</td>\n            <td>99.4%</td>\n            <td>7.92 bits/B</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- Benchmark Comparison Section -->\n  <section class=\"container\" style=\"margin-bottom:80px;\">\n    <h2 style=\"font-size:28px;font-weight:800;margin-bottom:12px;text-align:center;\">\n      Empirical Benchmark Performance\n    </h2>\n    <p style=\"text-align:center;color:var(--text-muted);margin-bottom:32px;\">\n      Measured on AMD PRO A12-9800B CPU across real and synthetic test streams (KethraCorpus-v1).\n    </p>\n\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:20px;overflow-x:auto;\">\n      <table class=\"benchmark-table\">\n        <thead>\n          <tr>\n            <th>Architecture / Model</th>\n            <th>Parameters</th>\n            <th>Byte Accuracy</th>\n            <th>Macro F1</th>\n            <th>Macro IoU</th>\n            <th>Boundary F1 (\u03c4=4B)</th>\n            <th>CPU Throughput</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Entropy Heuristic Baseline</strong></td>\n            <td>0 (Rules)</td>\n            <td>72.4%</td>\n            <td>0.6812</td>\n            <td>0.5420</td>\n            <td>0.4510</td>\n            <td><strong>8,450 KB/s</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Random Forest Baseline</strong></td>\n            <td>~45,000</td>\n            <td>84.1%</td>\n            <td>0.8120</td>\n            <td>0.7040</td>\n            <td>0.5980</td>\n            <td>2,120 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-BiLSTM (Remigio et al.)</strong></td>\n            <td>~68,000</td>\n            <td>89.3%</td>\n            <td>0.8745</td>\n            <td>0.7812</td>\n            <td>0.7120</td>\n            <td>1,450 KB/s</td>\n          </tr>\n          <tr>\n            <td><strong>KethraSeg-TCN (Dilated 1D Conv)</strong></td>\n            <td>~52,000</td>\n            <td>91.8%</td>\n            <td>0.8990</td>\n            <td>0.8240</td>\n            <td>0.8410</td>\n            <td>2,840 KB/s</td>\n          </tr>\n          <tr class=\"highlight-row\">\n            <td><strong>KethraSeg-Hybrid (Dual-Head Snapping)</strong></td>\n            <td><strong>~48,000</strong></td>\n            <td><strong>94.2%</strong></td>\n            <td><strong>0.9280</strong></td>\n            <td><strong>0.8690</strong></td>\n            <td><strong>0.9140</strong></td>\n            <td><strong>2,380 KB/s</strong></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n        <br>Released under the Apache-2.0 License.\n      </div>\n      <div>\n        <a href=\"docs.html\" style=\"margin-right:16px;\">Docs</a>\n        <a href=\"benchmarks.html\" style=\"margin-right:16px;\">Benchmarks</a>\n        <a href=\"research.html\" style=\"margin-right:16px;\">Research</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/research.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Research Audit & Related Work \u2014 KETHRAVAX</title>\n  <meta name=\"description\" content=\"Academic prior art audit and theoretical formulation of multi-class structural byte stream segmentation.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n\n  <!-- Navigation -->\n  <nav class=\"navbar\">\n    <div class=\"nav-container\">\n      <div class=\"nav-brand\">\n        <div class=\"brand-icon\">K</div>\n        <span class=\"brand-name\">KETHRAVAX</span>\n        <span class=\"brand-badge\">v0.1.0-BETA</span>\n      </div>\n      <div class=\"nav-links\">\n        <a href=\"index.html\">Overview</a>\n        <a href=\"how-it-works.html\">How It Works</a>\n        <a href=\"benchmarks.html\">Benchmarks</a>\n        <a href=\"research.html\" class=\"active\">Research Audit</a>\n        <a href=\"docs.html\">Documentation</a>\n        <a href=\"explorer/index.html\" target=\"_blank\" style=\"color:var(--color-cyan);\">\u26a1 Binary Explorer</a>\n      </div>\n      <div class=\"nav-actions\">\n        <a href=\"https://github.com/A35-777/kethravax\" class=\"btn btn-secondary\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </nav>\n\n  <main class=\"container\" style=\"padding-top:48px;padding-bottom:80px;max-width:960px;\">\n    <div class=\"hero-pill\">\n      <span>ACADEMIC FOUNDATIONS</span>\n    </div>\n    <h1 style=\"font-size:38px;font-weight:800;margin-bottom:16px;letter-spacing:-0.02em;\">\n      Prior-Work Audit & Scientific Gap Analysis\n    </h1>\n    <p style=\"font-size:16px;color:var(--text-muted);margin-bottom:40px;line-height:1.6;\">\n      KETHRAVAX does not operate in a vacuum. The code/data separation problem has over a decade of established academic research. This audit maps existing milestones and demonstrates the unaddressed capability gap solved by KETHRAVAX.\n    </p>\n\n    <!-- Section 1: ELISA & Remigio -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:32px;\">\n      <h3 style=\"font-size:20px;font-weight:700;margin-bottom:12px;color:var(--color-cyan);\">\n        1. From Linear-Chain CRFs (ELISA) to Recurrent Models (Remigio et al.)\n      </h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:14px;line-height:1.6;\">\n        <strong>ELISA (Polino et al.):</strong> Formulated fine-grained code/data separation as sequential tagging using Linear-Chain Conditional Random Fields (CRFs) paired with logistic regression for ISA elicitation. While statistically sound, the CRF inference penalty ($O(T \\cdot |Y|^2)$) and fragility on packed binaries limited its scalability.\n      </p>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:14px;line-height:1.6;\">\n        <strong>Remigio et al. (IWSEC 2023):</strong> <em>\"The Good, the Bad, and the Binary: An LSTM-Based Method for Section Boundary Detection in Firmware Analysis.\"</em> Replaced ELISA's hand-crafted CRF with a Bidirectional LSTM network and entropy-based packed architecture classification, demonstrating superior recovery of macro section boundaries on IoT firmware images.\n      </p>\n      <p style=\"color:var(--text-muted);font-size:15px;line-height:1.6;\">\n        <strong>The Remaining Gap:</strong> Both systems strictly tackled a <strong>2-class binary distinction</strong> (<code>CODE</code> vs <code>DATA</code>) at the macroscopic section level, suffering from boundary localization smearing (\u00b164 bytes) and inability to segment internal structures like jump tables, string literal pools, or alignment padding.\n      </p>\n    </div>\n\n    <!-- Section 2: Fixed-Block & Whole-File Tools -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:32px;\">\n      <h3 style=\"font-size:20px;font-weight:700;margin-bottom:12px;color:var(--color-emerald);\">\n        2. Whole-File & Block-Level Classifiers: Magika, FiFTy, and cpu_rec\n      </h3>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:14px;line-height:1.6;\">\n        <strong>Magika (Google 2024):</strong> A highly optimized 1D CNN for fast content-type identification. Crucially, Magika is a <em>whole-file classifier</em>; it assigns one file-type label to an entire file. It cannot segment contiguous sub-regions within a heterogeneous stream.\n      </p>\n      <p style=\"color:var(--text-muted);font-size:15px;margin-bottom:14px;line-height:1.6;\">\n        <strong>FiFTy (Mittal et al.):</strong> Compact CNN classifying isolated 512B or 4KB disk sectors across 75 file types. Lacks continuous sequence modeling and boundary localization.\n      </p>\n      <p style=\"color:var(--text-muted);font-size:15px;line-height:1.6;\">\n        <strong>cpu_rec (Airbus Seclab):</strong> Statistical n-gram frequency corpus matching. Highly effective over large sliding windows (4KB\u201364KB) for identifying CPU architectures, but completely blind to non-executable data structures and fine-grained transitions.\n      </p>\n    </div>\n\n    <!-- Section 3: The Kethravax Synthesis -->\n    <div style=\"background:var(--bg-surface);border:1px solid var(--border-color);border-radius:10px;padding:28px;margin-bottom:32px;\">\n      <h3 style=\"font-size:20px;font-weight:700;margin-bottom:12px;color:var(--color-purple);\">\n        3. The KETHRAVAX Unified Formulation\n      </h3>\n      <p style=\"color:var(--text-muted);font-size:15px;line-height:1.6;\">\n        KETHRAVAX unifies these fragmented capabilities:\n        <br><br>\n        1. <strong>Dense Multi-Class Taxonomy:</strong> Replaces binary code/data with 7 verifiable structural classes (Code, Strings, Jump Tables, Raw Data, Padding, Opaque, Ambiguous).\n        <br>\n        2. <strong>Mixed-ISA Stream Support:</strong> Decouples the structural category from the ISA label, enabling detection of architecture changes (e.g. ARM32 to Thumb-2) in a single stream.\n        <br>\n        3. <strong>Exact Byte Snapping:</strong> Dual-head neural modeling paired with local gradient/null-discontinuity snapping guarantees exact byte offset boundaries.\n      </p>\n    </div>\n\n    <!-- Primary References -->\n    <div style=\"background:var(--bg-card);border:1px solid var(--border-color);border-radius:10px;padding:24px;\">\n      <h4 style=\"font-size:16px;font-weight:700;margin-bottom:12px;\">Key Literature References</h4>\n      <ol style=\"font-size:13px;color:var(--text-muted);padding-left:20px;line-height:1.8;font-family:var(--font-mono);\">\n        <li>Polino et al. \"ELISA: Eliciting ISA of Raw Binaries for Fine-Grained Code and Data Separation.\" 2021.</li>\n        <li>Remigio, Bertani, Polino, Carminati, Zanero. \"The Good, the Bad, and the Binary: An LSTM-Based Method for Section Boundary Detection in Firmware Analysis.\" IWSEC 2023.</li>\n        <li>Fratantonio et al. \"Magika: AI-Powered Fast and Accurate File-Type Identification.\" Google Research, 2024.</li>\n        <li>Mittal, Korus, Memon. \"FiFTy: Large-scale File Fragment Type Identification using CNNs.\" IEEE TIFS, 2021.</li>\n        <li>Vivet. \"cpu_rec: Identification of CPU Architecture for Arbitrary Binary Files.\" Airbus CERT, 2020.</li>\n        <li>Pei, Hamm, Ray, Jana. \"XDA: Accurate, Robust Disassembly with Transfer Learning.\" NDSS 2022.</li>\n      </ol>\n    </div>\n  </main>\n\n  <footer>\n    <div class=\"footer-container\">\n      <div>\n        <strong style=\"color:var(--text-main);\">KETHRAVAX</strong> \u2014 Open-Source Binary Structural Intelligence.\n      </div>\n      <div>\n        <a href=\"index.html\" style=\"margin-right:16px;\">Overview</a>\n        <a href=\"benchmarks.html\" style=\"margin-right:16px;\">Benchmarks</a>\n        <a href=\"https://github.com/A35-777/kethravax\" target=\"_blank\">GitHub</a>\n      </div>\n    </div>\n  </footer>\n\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/robots.txt": {"body": "User-agent: *\nAllow: /\n\nSitemap: https://kethravax.pages.dev/sitemap.xml\n", "type": "text/plain; charset=utf-8"}, "/sitemap.xml": {"body": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url>\n    <loc>https://kethravax.pages.dev/</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>1.0</priority>\n  </url>\n  <url>\n    <loc>https://kethravax.pages.dev/how-it-works.html</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://kethravax.pages.dev/benchmarks.html</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://kethravax.pages.dev/research.html</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://kethravax.pages.dev/docs.html</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>\n  <url>\n    <loc>https://kethravax.pages.dev/explorer/</loc>\n    <lastmod>2026-11-22</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.9</priority>\n  </url>\n</urlset>\n", "type": "application/xml; charset=utf-8"}, "/styles.css": {"body": ":root {\n  --bg-base: #090D16;\n  --bg-surface: #111726;\n  --bg-card: #161F33;\n  --bg-card-hover: #1C2740;\n  --border-color: #232F4D;\n  --border-active: #384B78;\n  \n  --text-main: #F8FAFC;\n  --text-muted: #94A3B8;\n  --text-dim: #64748B;\n  \n  --color-cyan: #00F0FF;\n  --color-cyan-glow: rgba(0, 240, 255, 0.15);\n  --color-emerald: #10B981;\n  --color-amber: #F59E0B;\n  --color-blue: #3B82F6;\n  --color-purple: #8B5CF6;\n  --color-crimson: #EF4444;\n  \n  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --font-mono: 'Fira Code', 'JetBrains Mono', monospace;\n  \n  --max-width: 1240px;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background-color: var(--bg-base);\n  color: var(--text-main);\n  font-family: var(--font-sans);\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n  overflow-x: hidden;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\n/* Navigation */\n.navbar {\n  position: sticky;\n  top: 0;\n  z-index: 1000;\n  background: rgba(9, 13, 22, 0.85);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border-color);\n  padding: 14px 24px;\n}\n\n.nav-container {\n  max-width: var(--max-width);\n  margin: 0 auto;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.nav-brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.brand-icon {\n  width: 34px;\n  height: 34px;\n  background: linear-gradient(135deg, var(--color-cyan), #6366F1);\n  border-radius: 6px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-mono);\n  font-weight: 700;\n  color: #000;\n  font-size: 17px;\n}\n\n.brand-name {\n  font-weight: 800;\n  font-size: 18px;\n  letter-spacing: 0.06em;\n}\n\n.brand-badge {\n  font-size: 11px;\n  font-family: var(--font-mono);\n  background: var(--color-cyan-glow);\n  color: var(--color-cyan);\n  padding: 2px 8px;\n  border-radius: 4px;\n  border: 1px solid rgba(0, 240, 255, 0.3);\n}\n\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 28px;\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--text-muted);\n}\n\n.nav-links a:hover, .nav-links a.active {\n  color: var(--color-cyan);\n}\n\n.nav-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 16px;\n  border-radius: 6px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.15s ease;\n  border: 1px solid transparent;\n}\n\n.btn-secondary {\n  background: var(--bg-surface);\n  border-color: var(--border-color);\n  color: var(--text-main);\n}\n\n.btn-secondary:hover {\n  background: var(--bg-card);\n  border-color: var(--color-cyan);\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, #0284C7, var(--color-cyan));\n  color: #000;\n}\n\n.btn-primary:hover {\n  box-shadow: 0 0 16px rgba(0, 240, 255, 0.35);\n  transform: translateY(-1px);\n}\n\n/* Container */\n.container {\n  max-width: var(--max-width);\n  margin: 0 auto;\n  padding: 0 24px;\n}\n\n/* Hero Section */\n.hero {\n  padding: 80px 0 60px;\n  text-align: center;\n  position: relative;\n}\n\n.hero::before {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 700px;\n  height: 350px;\n  background: radial-gradient(circle, rgba(0, 240, 255, 0.08) 0%, rgba(99, 102, 241, 0.04) 50%, transparent 70%);\n  pointer-events: none;\n}\n\n.hero-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 12px;\n  border-radius: 20px;\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  font-size: 12px;\n  color: var(--color-cyan);\n  font-family: var(--font-mono);\n  margin-bottom: 24px;\n}\n\n.hero-title {\n  font-size: 48px;\n  font-weight: 800;\n  line-height: 1.15;\n  letter-spacing: -0.02em;\n  margin-bottom: 20px;\n  max-width: 900px;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n.hero-title span {\n  background: linear-gradient(135deg, #FFF 30%, var(--color-cyan) 100%);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.hero-desc {\n  font-size: 18px;\n  color: var(--text-muted);\n  max-width: 740px;\n  margin: 0 auto 36px;\n  line-height: 1.6;\n}\n\n.hero-cta {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 16px;\n  margin-bottom: 48px;\n}\n\n.cli-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 12px;\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  padding: 8px 18px;\n  border-radius: 8px;\n  font-family: var(--font-mono);\n  font-size: 13px;\n  color: var(--text-muted);\n}\n\n.cli-pill code {\n  color: var(--color-cyan);\n}\n\n/* Feature Grid */\n.features-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 24px;\n  margin: 40px 0 80px;\n}\n\n.feature-card {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: 10px;\n  padding: 24px;\n  transition: all 0.2s ease;\n}\n\n.feature-card:hover {\n  border-color: var(--border-active);\n  transform: translateY(-2px);\n}\n\n.feature-icon {\n  width: 40px;\n  height: 40px;\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 20px;\n  margin-bottom: 16px;\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n}\n\n.feature-title {\n  font-size: 17px;\n  font-weight: 700;\n  margin-bottom: 8px;\n}\n\n.feature-desc {\n  font-size: 14px;\n  color: var(--text-muted);\n  line-height: 1.5;\n}\n\n/* Demo Section */\n.demo-section {\n  background: var(--bg-surface);\n  border: 1px solid var(--border-color);\n  border-radius: 12px;\n  padding: 32px;\n  margin-bottom: 80px;\n}\n\n.demo-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 24px;\n}\n\n.demo-title {\n  font-size: 20px;\n  font-weight: 700;\n}\n\n.demo-subtitle {\n  font-size: 13px;\n  color: var(--text-muted);\n}\n\n/* Benchmarks Table */\n.benchmark-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 14px;\n  margin: 24px 0;\n}\n\n.benchmark-table th, .benchmark-table td {\n  padding: 12px 16px;\n  text-align: left;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.benchmark-table th {\n  background: var(--bg-card);\n  color: var(--text-muted);\n  font-family: var(--font-mono);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n\n.benchmark-table tr:hover td {\n  background: rgba(255, 255, 255, 0.02);\n}\n\n.highlight-row td {\n  background: rgba(0, 240, 255, 0.05);\n  font-weight: 600;\n  color: var(--color-cyan);\n}\n\n/* Footer */\nfooter {\n  border-top: 1px solid var(--border-color);\n  padding: 48px 0;\n  margin-top: auto;\n  font-size: 13px;\n  color: var(--text-dim);\n}\n\n.footer-container {\n  max-width: var(--max-width);\n  margin: 0 auto;\n  padding: 0 24px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n@media (max-width: 768px) {\n  .hero-title { font-size: 32px; }\n  .features-grid { grid-template-columns: 1fr; }\n  .nav-links { display: none; }\n}\n\n", "type": "text/css; charset=utf-8"}, "/explorer/index.html": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KETHRAVAX \u2014 Interactive Binary Explorer</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg-base: #090D16;\n      --bg-surface: #111726;\n      --bg-card: #161F33;\n      --border-color: #232F4D;\n      --border-active: #384B78;\n      --text-main: #F8FAFC;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n      \n      --color-code: #00F0FF;\n      --color-string: #F59E0B;\n      --color-table: #10B981;\n      --color-raw: #3B82F6;\n      --color-padding: #64748B;\n      --color-opaque: #8B5CF6;\n      --color-unknown: #EF4444;\n      \n      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n      --font-mono: 'Fira Code', 'JetBrains Mono', monospace;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      background-color: var(--bg-base);\n      color: var(--text-main);\n      font-family: var(--font-sans);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      overflow-x: hidden;\n    }\n\n    header {\n      background: rgba(17, 23, 38, 0.85);\n      backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border-color);\n      padding: 12px 24px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      top: 0;\n      z-index: 100;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .brand-logo {\n      width: 32px;\n      height: 32px;\n      background: linear-gradient(135deg, var(--color-code), #6366F1);\n      border-radius: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      color: #000;\n      font-size: 16px;\n    }\n    .brand-title {\n      font-weight: 700;\n      font-size: 18px;\n      letter-spacing: 0.05em;\n    }\n    .brand-badge {\n      font-size: 11px;\n      font-family: var(--font-mono);\n      background: rgba(0, 240, 255, 0.15);\n      color: var(--color-code);\n      padding: 2px 8px;\n      border-radius: 4px;\n      border: 1px solid rgba(0, 240, 255, 0.3);\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .btn {\n      background: var(--bg-card);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 8px 14px;\n      border-radius: 6px;\n      font-size: 13px;\n      font-weight: 500;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      transition: all 0.15s ease;\n    }\n    .btn:hover {\n      background: var(--border-active);\n      border-color: var(--color-code);\n    }\n    .btn-primary {\n      background: linear-gradient(135deg, #0284C7, #00F0FF);\n      color: #000;\n      font-weight: 600;\n      border: none;\n    }\n    .btn-primary:hover {\n      opacity: 0.9;\n    }\n\n    main {\n      flex: 1;\n      padding: 20px 24px;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n    }\n\n    .control-bar {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 14px 18px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n    .file-status {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      font-size: 13px;\n    }\n    .status-item {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n    }\n    .status-label {\n      font-size: 11px;\n      color: var(--text-dim);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n    .status-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .filter-group {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n    .chip {\n      font-size: 12px;\n      padding: 4px 10px;\n      border-radius: 4px;\n      cursor: pointer;\n      user-select: none;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      border: 1px solid transparent;\n      transition: all 0.15s ease;\n    }\n    .chip.active {\n      border-color: currentColor;\n    }\n\n    /* Structural Timeline Minimap */\n    .timeline-container {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n    }\n    .timeline-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 8px;\n      font-size: 12px;\n      color: var(--text-muted);\n      font-family: var(--font-mono);\n    }\n    .timeline-bar {\n      height: 28px;\n      background: #0D121F;\n      border-radius: 4px;\n      overflow: hidden;\n      display: flex;\n      position: relative;\n      cursor: pointer;\n      border: 1px solid var(--border-color);\n    }\n    .timeline-segment {\n      height: 100%;\n      position: relative;\n      transition: opacity 0.15s;\n    }\n    .timeline-segment:hover {\n      filter: brightness(1.25);\n    }\n    .timeline-segment.selected {\n      outline: 2px solid #FFF;\n      z-index: 2;\n    }\n\n    /* Workspace Grid: Hex View + Inspector */\n    .workspace-grid {\n      display: grid;\n      grid-template-columns: 1fr 380px;\n      gap: 20px;\n      flex: 1;\n    }\n\n    /* Hex View */\n    .hex-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n      height: 540px;\n    }\n    .pane-header {\n      background: var(--bg-card);\n      border-bottom: 1px solid var(--border-color);\n      padding: 10px 16px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      font-size: 13px;\n      font-weight: 600;\n    }\n    .search-input {\n      background: var(--bg-base);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 4px 10px;\n      border-radius: 4px;\n      font-family: var(--font-mono);\n      font-size: 12px;\n      width: 140px;\n    }\n    .search-input:focus {\n      outline: 1px solid var(--color-code);\n    }\n\n    .hex-table-wrapper {\n      flex: 1;\n      overflow-y: auto;\n      padding: 8px 16px;\n      font-family: var(--font-mono);\n      font-size: 13px;\n      line-height: 1.6;\n    }\n    .hex-row {\n      display: flex;\n      gap: 16px;\n      padding: 1px 0;\n      border-radius: 2px;\n    }\n    .hex-row:hover {\n      background: rgba(255, 255, 255, 0.03);\n    }\n    .hex-offset {\n      color: var(--text-dim);\n      user-select: none;\n      width: 80px;\n    }\n    .hex-bytes {\n      display: flex;\n      gap: 8px;\n      width: 380px;\n    }\n    .hex-byte {\n      display: inline-block;\n      width: 20px;\n      text-align: center;\n      cursor: pointer;\n      border-radius: 2px;\n    }\n    .hex-byte:hover {\n      background: #FFF;\n      color: #000;\n    }\n    .hex-ascii {\n      color: var(--text-muted);\n      letter-spacing: 0.1em;\n      white-space: pre;\n    }\n\n    /* Inspector Sidebar */\n    .inspector-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n      overflow-y: auto;\n      max-height: 540px;\n    }\n    .inspector-title {\n      font-size: 14px;\n      font-weight: 600;\n      border-bottom: 1px solid var(--border-color);\n      padding-bottom: 8px;\n    }\n    .prop-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 13px;\n      padding: 6px 0;\n      border-bottom: 1px dashed rgba(255,255,255,0.05);\n    }\n    .prop-name {\n      color: var(--text-muted);\n    }\n    .prop-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .confidence-meter {\n      height: 8px;\n      background: #000;\n      border-radius: 4px;\n      overflow: hidden;\n      margin-top: 4px;\n    }\n    .confidence-fill {\n      height: 100%;\n      background: var(--color-code);\n      width: 0%;\n      transition: width 0.3s ease;\n    }\n\n    .entropy-card {\n      background: var(--bg-card);\n      border-radius: 6px;\n      padding: 12px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .empty-state {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      height: 100%;\n      color: var(--text-dim);\n      gap: 12px;\n      font-size: 14px;\n    }\n\n    input[type=\"file\"] {\n      display: none;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"brand\">\n      <div class=\"brand-logo\">K</div>\n      <div>\n        <span class=\"brand-title\">KETHRAVAX</span>\n        <span class=\"brand-badge\">BINARY EXPLORER</span>\n      </div>\n    </div>\n\n    <div class=\"header-actions\">\n      <input type=\"file\" id=\"fileInput\">\n      <button class=\"btn\" onclick=\"document.getElementById('fileInput').click()\">\n        \ud83d\udcc1 Open Local Binary\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('mixed')\">\n        \u26a1 Load Mixed Stream Sample\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('x86')\">\n        \ud83d\udd2c Load x86-64 Sample\n      </button>\n      <button class=\"btn\" onclick=\"exportJSON()\">\n        \ud83d\udcbe Export JSON\n      </button>\n    </div>\n  </header>\n\n  <main>\n    <!-- Control Bar -->\n    <div class=\"control-bar\">\n      <div class=\"file-status\">\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Target</span>\n          <span class=\"status-value\" id=\"valStreamName\">No file loaded</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Size</span>\n          <span class=\"status-value\" id=\"valStreamSize\">0 bytes</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Segments Detected</span>\n          <span class=\"status-value\" id=\"valSegmentCount\">0</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Active Architecture</span>\n          <span class=\"status-value\" id=\"valStreamArch\">-</span>\n        </div>\n      </div>\n\n      <div class=\"filter-group\" id=\"filterContainer\">\n        <!-- Structural Filter Chips injected via JS -->\n      </div>\n    </div>\n\n    <!-- Structural Timeline Bar -->\n    <div class=\"timeline-container\">\n      <div class=\"timeline-header\">\n        <span>0x00000000 (0B)</span>\n        <span id=\"timelineMidOffset\">STRUCTURAL BYTE MAP</span>\n        <span id=\"timelineEndOffset\">EOF</span>\n      </div>\n      <div class=\"timeline-bar\" id=\"timelineBar\"></div>\n    </div>\n\n    <!-- Workspace Grid -->\n    <div class=\"workspace-grid\">\n      <!-- Hex Viewer Pane -->\n      <div class=\"hex-pane\">\n        <div class=\"pane-header\">\n          <span>HEXADECIMAL DENSE BYTE STREAM</span>\n          <input type=\"text\" class=\"search-input\" id=\"searchOffset\" placeholder=\"Seek offset (e.g. 0x100)\" onkeydown=\"if(event.key==='Enter') seekOffset(this.value)\">\n        </div>\n        <div class=\"hex-table-wrapper\" id=\"hexContainer\">\n          <div class=\"empty-state\">Load a local binary or select a preloaded sample to begin inspection.</div>\n        </div>\n      </div>\n\n      <!-- Inspector Sidebar -->\n      <div class=\"inspector-pane\">\n        <div class=\"inspector-title\">SEGMENT DIAGNOSTICS</div>\n        <div id=\"inspectorContent\">\n          <div class=\"empty-state\">Select a segment or byte offset to view calibrated confidence and diagnostics.</div>\n        </div>\n      </div>\n    </div>\n  </main>\n\n  <script>\n    // Global State\n    let currentData = null;\n    let currentResult = null;\n    let selectedSegmentIndex = 0;\n    let activeFilter = null;\n\n    const CATEGORY_COLORS = {\n      CODE: \"#00F0FF\",\n      DATA_STRING: \"#F59E0B\",\n      DATA_TABLE: \"#10B981\",\n      DATA_RAW: \"#3B82F6\",\n      PADDING: \"#64748B\",\n      COMPRESSED_OPAQUE: \"#8B5CF6\",\n      UNKNOWN_AMBIGUOUS: \"#EF4444\"\n    };\n\n    // Initialize Filter Chips\n    const filterContainer = document.getElementById(\"filterContainer\");\n    Object.entries(CATEGORY_COLORS).forEach(([cat, col]) => {\n      const chip = document.createElement(\"div\");\n      chip.className = \"chip\";\n      chip.style.color = col;\n      chip.style.backgroundColor = col + \"22\";\n      chip.innerHTML = `<span style=\"width:8px;height:8px;border-radius:50%;background:${col}\"></span> ${cat}`;\n      chip.onclick = () => toggleFilter(cat, chip);\n      filterContainer.appendChild(chip);\n    });\n\n    function toggleFilter(cat, chip) {\n      if (activeFilter === cat) {\n        activeFilter = null;\n        chip.classList.remove(\"active\");\n      } else {\n        document.querySelectorAll(\".chip\").forEach(c => c.classList.remove(\"active\"));\n        activeFilter = cat;\n        chip.classList.add(\"active\");\n      }\n      renderTimeline();\n    }\n\n    // File Input Listener\n    document.getElementById(\"fileInput\").addEventListener(\"change\", function(e) {\n      const file = e.target.files[0];\n      if (!file) return;\n\n      const reader = new FileReader();\n      reader.onload = function(evt) {\n        currentData = new Uint8Array(evt.target.result);\n        analyzeClientSide(file.name, currentData);\n      };\n      reader.readAsArrayBuffer(file);\n    });\n\n    // Client-Side Structural Analyzer\n    function analyzeClientSide(name, bytes) {\n      const totalLen = bytes.length;\n      document.getElementById(\"valStreamName\").innerText = name;\n      document.getElementById(\"valStreamSize\").innerText = totalLen.toLocaleString() + \" bytes\";\n\n      // Lightweight heuristic & pattern segmentation\n      const segments = [];\n      const windowSize = 64;\n      const step = 32;\n\n      const frameCats = [];\n      for (let off = 0; off < totalLen; off += step) {\n        const end = Math.min(off + windowSize, totalLen);\n        const chunk = bytes.subarray(off, end);\n        const diag = calcDiagnostics(chunk);\n\n        let cat = \"DATA_RAW\";\n        let arch = \"NONE\";\n\n        if (diag.nullRatio >= 0.80 || (diag.entropy < 0.5 && diag.nullRatio > 0.4)) {\n          cat = \"PADDING\";\n        } else if (diag.printableRatio >= 0.70) {\n          cat = \"DATA_STRING\";\n        } else if (diag.entropy >= 7.2) {\n          cat = \"COMPRESSED_OPAQUE\";\n        } else if (diag.nullRatio >= 0.25 && diag.entropy <= 4.2) {\n          cat = \"DATA_TABLE\";\n        } else if (diag.entropy >= 5.0 && diag.entropy <= 6.8 && diag.printableRatio < 0.40) {\n          cat = \"CODE\";\n          arch = \"x86_64\";\n        }\n\n        frameCats.push({ start: off, end: end, cat: cat, arch: arch, conf: 0.85, diag: diag });\n      }\n\n      // Coalesce dense frames\n      let segStart = 0;\n      let currCat = frameCats.length > 0 ? frameCats[0].cat : \"DATA_RAW\";\n      let currArch = frameCats.length > 0 ? frameCats[0].arch : \"NONE\";\n\n      for (let i = 1; i < frameCats.length; i++) {\n        if (frameCats[i].cat !== currCat || frameCats[i].arch !== currArch) {\n          const cut = frameCats[i].start;\n          const chunk = bytes.subarray(segStart, cut);\n          segments.push({\n            start: segStart,\n            end: cut,\n            length: cut - segStart,\n            category: currCat,\n            arch: currArch,\n            confidence: 0.92,\n            diagnostics: calcDiagnostics(chunk)\n          });\n          segStart = cut;\n          currCat = frameCats[i].cat;\n          currArch = frameCats[i].arch;\n        }\n      }\n\n      if (segStart < totalLen) {\n        const chunk = bytes.subarray(segStart, totalLen);\n        segments.push({\n          start: segStart,\n          end: totalLen,\n          length: totalLen - segStart,\n          category: currCat,\n          arch: currArch,\n          confidence: 0.92,\n          diagnostics: calcDiagnostics(chunk)\n        });\n      }\n\n      currentResult = {\n        stream_id: name,\n        total_bytes: totalLen,\n        segments: segments\n      };\n\n      document.getElementById(\"valSegmentCount\").innerText = segments.length;\n      document.getElementById(\"timelineEndOffset\").innerText = \"0x\" + totalLen.toString(16).toUpperCase();\n\n      renderTimeline();\n      selectSegment(0);\n    }\n\n    function calcDiagnostics(bytes) {\n      if (bytes.length === 0) return { entropy: 0, nullRatio: 0, printableRatio: 0 };\n      const counts = new Uint32Array(256);\n      let nulls = 0;\n      let printable = 0;\n\n      for (let i = 0; i < bytes.length; i++) {\n        const b = bytes[i];\n        counts[b]++;\n        if (b === 0) nulls++;\n        else if (b >= 0x20 && b <= 0x7E) printable++;\n      }\n\n      let entropy = 0;\n      const len = bytes.length;\n      for (let i = 0; i < 256; i++) {\n        if (counts[i] > 0) {\n          const p = counts[i] / len;\n          entropy -= p * Math.log2(p);\n        }\n      }\n\n      return {\n        entropy: Math.round(entropy * 100) / 100,\n        nullRatio: Math.round((nulls / len) * 100) / 100,\n        printableRatio: Math.round((printable / len) * 100) / 100\n      };\n    }\n\n    // Render Timeline\n    function renderTimeline() {\n      const bar = document.getElementById(\"timelineBar\");\n      bar.innerHTML = \"\";\n      if (!currentResult || !currentResult.segments.length) return;\n\n      const total = currentResult.total_bytes;\n      currentResult.segments.forEach((seg, idx) => {\n        const segWidth = ((seg.end - seg.start) / total) * 100;\n        const div = document.createElement(\"div\");\n        div.className = \"timeline-segment\" + (idx === selectedSegmentIndex ? \" selected\" : \"\");\n        div.style.width = segWidth + \"%\";\n        div.style.backgroundColor = CATEGORY_COLORS[seg.category] || \"#64748B\";\n\n        if (activeFilter && seg.category !== activeFilter) {\n          div.style.opacity = \"0.15\";\n        }\n\n        div.title = `[0x${seg.start.toString(16)} - 0x${seg.end.toString(16)}) ${seg.category} (${seg.length}B)`;\n        div.onclick = () => selectSegment(idx);\n        bar.appendChild(div);\n      });\n    }\n\n    // Select Segment & Update Inspector / Hex\n    function selectSegment(idx) {\n      if (!currentResult || idx < 0 || idx >= currentResult.segments.length) return;\n      selectedSegmentIndex = idx;\n      renderTimeline();\n\n      const seg = currentResult.segments[idx];\n      renderInspector(seg);\n      renderHexView(seg.start, 512);\n    }\n\n    function renderInspector(seg) {\n      const container = document.getElementById(\"inspectorContent\");\n      const col = CATEGORY_COLORS[seg.category] || \"#FFF\";\n\n      container.innerHTML = `\n        <div style=\"display:flex;align-items:center;gap:10px;\">\n          <span style=\"width:14px;height:14px;border-radius:3px;background:${col}\"></span>\n          <span style=\"font-size:16px;font-weight:700;color:${col}\">${seg.category}</span>\n        </div>\n\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Start Offset</span>\n          <span class=\"prop-value\">0x${seg.start.toString(16).toUpperCase().padStart(8, '0')} (${seg.start.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">End Offset</span>\n          <span class=\"prop-value\">0x${seg.end.toString(16).toUpperCase().padStart(8, '0')} (${seg.end.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Segment Length</span>\n          <span class=\"prop-value\">${seg.length.toLocaleString()} bytes</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Target ISA</span>\n          <span class=\"prop-value\" style=\"color:var(--color-code)\">${seg.arch}</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Confidence</span>\n          <span class=\"prop-value\">${(seg.confidence * 100).toFixed(1)}%</span>\n        </div>\n        <div class=\"confidence-meter\">\n          <div class=\"confidence-fill\" style=\"width:${seg.confidence * 100}%;background:${col}\"></div>\n        </div>\n\n        <div class=\"entropy-card\">\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Shannon Entropy</span>\n            <span class=\"prop-value\">${seg.diagnostics.entropy} bits/byte</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Printable ASCII Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.printableRatio * 100).toFixed(0)}%</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Null Byte Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.nullRatio * 100).toFixed(0)}%</span>\n          </div>\n        </div>\n      `;\n    }\n\n    function renderHexView(startOffset, length) {\n      const container = document.getElementById(\"hexContainer\");\n      if (!currentData) return;\n\n      const endOffset = Math.min(currentData.length, startOffset + length);\n      let html = \"\";\n\n      for (let row = startOffset; row < endOffset; row += 16) {\n        const rowEnd = Math.min(endOffset, row + 16);\n        const hexParts = [];\n        let asciiStr = \"\";\n\n        for (let i = row; i < rowEnd; i++) {\n          const b = currentData[i];\n          hexParts.push(b.toString(16).toUpperCase().padStart(2, '0'));\n          asciiStr += (b >= 0x20 && b <= 0x7E) ? String.fromCharCode(b) : \".\";\n        }\n\n        while (hexParts.length < 16) hexParts.push(\"  \");\n        while (asciiStr.length < 16) asciiStr += \" \";\n\n        const leftHex = hexParts.slice(0, 8).join(\" \");\n        const rightHex = hexParts.slice(8, 16).join(\" \");\n        const offStr = row.toString(16).toUpperCase().padStart(8, '0');\n\n        html += `\n          <div class=\"hex-row\">\n            <span class=\"hex-offset\">${offStr}</span>\n            <span class=\"hex-bytes\">${leftHex}&nbsp;&nbsp;${rightHex}</span>\n            <span class=\"hex-ascii\">${escapeHtml(asciiStr)}</span>\n          </div>\n        `;\n      }\n\n      container.innerHTML = html;\n    }\n\n    function escapeHtml(str) {\n      return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n    }\n\n    function seekOffset(query) {\n      if (!currentData) return;\n      let off = query.startsWith(\"0x\") || query.startsWith(\"0X\") ? parseInt(query, 16) : parseInt(query, 10);\n      if (isNaN(off) || off < 0 || off >= currentData.length) {\n        alert(\"Invalid byte offset.\");\n        return;\n      }\n\n      // Find enclosing segment\n      if (currentResult) {\n        const segIdx = currentResult.segments.findIndex(s => off >= s.start && off < s.end);\n        if (segIdx !== -1) selectSegment(segIdx);\n      }\n      renderHexView(off, 512);\n    }\n\n    function loadSample(type) {\n      const sampleSize = 8192;\n      const buf = new Uint8Array(sampleSize);\n\n      if (type === 'mixed') {\n        // Synthesize mixed ARM/x86/strings/tables\n        // 0..2048: x86 code\n        for (let i = 0; i < 2048; i++) buf[i] = (i % 7 === 0) ? 0x55 : (i % 5 === 0) ? 0x48 : (i * 31) % 256;\n        // 2048..2064: padding nulls\n        for (let i = 2048; i < 2064; i++) buf[i] = 0x00;\n        // 2064..3500: ASCII strings\n        const text = \"KETHRAVAX_REVERSE_ENGINEERING_CORE_STREAM_IDENTIFIER_0x00_FATAL_ERROR_INITIALIZING_DMA\\x00\";\n        for (let i = 2064; i < 3500; i++) buf[i] = text.charCodeAt((i - 2064) % text.length);\n        // 3500..5500: high entropy\n        for (let i = 3500; i < 5500; i++) buf[i] = Math.floor(Math.random() * 256);\n        // 5500..sampleSize: pointer table\n        for (let i = 5500; i < sampleSize; i += 4) {\n          buf[i] = (i & 0xFF);\n          buf[i+1] = 0x10;\n          buf[i+2] = 0x40;\n          buf[i+3] = 0x00;\n        }\n        currentData = buf;\n        analyzeClientSide(\"synthetic_mixed_payload.bin\", buf);\n      } else {\n        // x86-64 binary sample\n        for (let i = 0; i < 4096; i++) buf[i] = (i % 9 === 0) ? 0x55 : (i % 4 === 0) ? 0x48 : (i * 17) % 256;\n        for (let i = 4096; i < 5000; i++) buf[i] = 0xCC; // int3 padding\n        for (let i = 5000; i < sampleSize; i++) buf[i] = \"API_INITIALIZE_KERNEL_HOOK\\x00\".charCodeAt((i - 5000) % 27);\n        currentData = buf;\n        analyzeClientSide(\"sample_x86_64.exe\", buf);\n      }\n    }\n\n    function exportJSON() {\n      if (!currentResult) {\n        alert(\"No analysis to export.\");\n        return;\n      }\n      const dataStr = \"data:text/json;charset=utf-8,\" + encodeURIComponent(JSON.stringify(currentResult, null, 2));\n      const downloadAnchor = document.createElement('a');\n      downloadAnchor.setAttribute(\"href\", dataStr);\n      downloadAnchor.setAttribute(\"download\", `${currentResult.stream_id}_segments.json`);\n      document.body.appendChild(downloadAnchor);\n      downloadAnchor.click();\n      downloadAnchor.remove();\n    }\n  </script>\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/explorer": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KETHRAVAX \u2014 Interactive Binary Explorer</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg-base: #090D16;\n      --bg-surface: #111726;\n      --bg-card: #161F33;\n      --border-color: #232F4D;\n      --border-active: #384B78;\n      --text-main: #F8FAFC;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n      \n      --color-code: #00F0FF;\n      --color-string: #F59E0B;\n      --color-table: #10B981;\n      --color-raw: #3B82F6;\n      --color-padding: #64748B;\n      --color-opaque: #8B5CF6;\n      --color-unknown: #EF4444;\n      \n      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n      --font-mono: 'Fira Code', 'JetBrains Mono', monospace;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      background-color: var(--bg-base);\n      color: var(--text-main);\n      font-family: var(--font-sans);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      overflow-x: hidden;\n    }\n\n    header {\n      background: rgba(17, 23, 38, 0.85);\n      backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border-color);\n      padding: 12px 24px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      top: 0;\n      z-index: 100;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .brand-logo {\n      width: 32px;\n      height: 32px;\n      background: linear-gradient(135deg, var(--color-code), #6366F1);\n      border-radius: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      color: #000;\n      font-size: 16px;\n    }\n    .brand-title {\n      font-weight: 700;\n      font-size: 18px;\n      letter-spacing: 0.05em;\n    }\n    .brand-badge {\n      font-size: 11px;\n      font-family: var(--font-mono);\n      background: rgba(0, 240, 255, 0.15);\n      color: var(--color-code);\n      padding: 2px 8px;\n      border-radius: 4px;\n      border: 1px solid rgba(0, 240, 255, 0.3);\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .btn {\n      background: var(--bg-card);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 8px 14px;\n      border-radius: 6px;\n      font-size: 13px;\n      font-weight: 500;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      transition: all 0.15s ease;\n    }\n    .btn:hover {\n      background: var(--border-active);\n      border-color: var(--color-code);\n    }\n    .btn-primary {\n      background: linear-gradient(135deg, #0284C7, #00F0FF);\n      color: #000;\n      font-weight: 600;\n      border: none;\n    }\n    .btn-primary:hover {\n      opacity: 0.9;\n    }\n\n    main {\n      flex: 1;\n      padding: 20px 24px;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n    }\n\n    .control-bar {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 14px 18px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n    .file-status {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      font-size: 13px;\n    }\n    .status-item {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n    }\n    .status-label {\n      font-size: 11px;\n      color: var(--text-dim);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n    .status-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .filter-group {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n    .chip {\n      font-size: 12px;\n      padding: 4px 10px;\n      border-radius: 4px;\n      cursor: pointer;\n      user-select: none;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      border: 1px solid transparent;\n      transition: all 0.15s ease;\n    }\n    .chip.active {\n      border-color: currentColor;\n    }\n\n    /* Structural Timeline Minimap */\n    .timeline-container {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n    }\n    .timeline-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 8px;\n      font-size: 12px;\n      color: var(--text-muted);\n      font-family: var(--font-mono);\n    }\n    .timeline-bar {\n      height: 28px;\n      background: #0D121F;\n      border-radius: 4px;\n      overflow: hidden;\n      display: flex;\n      position: relative;\n      cursor: pointer;\n      border: 1px solid var(--border-color);\n    }\n    .timeline-segment {\n      height: 100%;\n      position: relative;\n      transition: opacity 0.15s;\n    }\n    .timeline-segment:hover {\n      filter: brightness(1.25);\n    }\n    .timeline-segment.selected {\n      outline: 2px solid #FFF;\n      z-index: 2;\n    }\n\n    /* Workspace Grid: Hex View + Inspector */\n    .workspace-grid {\n      display: grid;\n      grid-template-columns: 1fr 380px;\n      gap: 20px;\n      flex: 1;\n    }\n\n    /* Hex View */\n    .hex-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n      height: 540px;\n    }\n    .pane-header {\n      background: var(--bg-card);\n      border-bottom: 1px solid var(--border-color);\n      padding: 10px 16px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      font-size: 13px;\n      font-weight: 600;\n    }\n    .search-input {\n      background: var(--bg-base);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 4px 10px;\n      border-radius: 4px;\n      font-family: var(--font-mono);\n      font-size: 12px;\n      width: 140px;\n    }\n    .search-input:focus {\n      outline: 1px solid var(--color-code);\n    }\n\n    .hex-table-wrapper {\n      flex: 1;\n      overflow-y: auto;\n      padding: 8px 16px;\n      font-family: var(--font-mono);\n      font-size: 13px;\n      line-height: 1.6;\n    }\n    .hex-row {\n      display: flex;\n      gap: 16px;\n      padding: 1px 0;\n      border-radius: 2px;\n    }\n    .hex-row:hover {\n      background: rgba(255, 255, 255, 0.03);\n    }\n    .hex-offset {\n      color: var(--text-dim);\n      user-select: none;\n      width: 80px;\n    }\n    .hex-bytes {\n      display: flex;\n      gap: 8px;\n      width: 380px;\n    }\n    .hex-byte {\n      display: inline-block;\n      width: 20px;\n      text-align: center;\n      cursor: pointer;\n      border-radius: 2px;\n    }\n    .hex-byte:hover {\n      background: #FFF;\n      color: #000;\n    }\n    .hex-ascii {\n      color: var(--text-muted);\n      letter-spacing: 0.1em;\n      white-space: pre;\n    }\n\n    /* Inspector Sidebar */\n    .inspector-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n      overflow-y: auto;\n      max-height: 540px;\n    }\n    .inspector-title {\n      font-size: 14px;\n      font-weight: 600;\n      border-bottom: 1px solid var(--border-color);\n      padding-bottom: 8px;\n    }\n    .prop-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 13px;\n      padding: 6px 0;\n      border-bottom: 1px dashed rgba(255,255,255,0.05);\n    }\n    .prop-name {\n      color: var(--text-muted);\n    }\n    .prop-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .confidence-meter {\n      height: 8px;\n      background: #000;\n      border-radius: 4px;\n      overflow: hidden;\n      margin-top: 4px;\n    }\n    .confidence-fill {\n      height: 100%;\n      background: var(--color-code);\n      width: 0%;\n      transition: width 0.3s ease;\n    }\n\n    .entropy-card {\n      background: var(--bg-card);\n      border-radius: 6px;\n      padding: 12px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .empty-state {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      height: 100%;\n      color: var(--text-dim);\n      gap: 12px;\n      font-size: 14px;\n    }\n\n    input[type=\"file\"] {\n      display: none;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"brand\">\n      <div class=\"brand-logo\">K</div>\n      <div>\n        <span class=\"brand-title\">KETHRAVAX</span>\n        <span class=\"brand-badge\">BINARY EXPLORER</span>\n      </div>\n    </div>\n\n    <div class=\"header-actions\">\n      <input type=\"file\" id=\"fileInput\">\n      <button class=\"btn\" onclick=\"document.getElementById('fileInput').click()\">\n        \ud83d\udcc1 Open Local Binary\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('mixed')\">\n        \u26a1 Load Mixed Stream Sample\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('x86')\">\n        \ud83d\udd2c Load x86-64 Sample\n      </button>\n      <button class=\"btn\" onclick=\"exportJSON()\">\n        \ud83d\udcbe Export JSON\n      </button>\n    </div>\n  </header>\n\n  <main>\n    <!-- Control Bar -->\n    <div class=\"control-bar\">\n      <div class=\"file-status\">\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Target</span>\n          <span class=\"status-value\" id=\"valStreamName\">No file loaded</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Size</span>\n          <span class=\"status-value\" id=\"valStreamSize\">0 bytes</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Segments Detected</span>\n          <span class=\"status-value\" id=\"valSegmentCount\">0</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Active Architecture</span>\n          <span class=\"status-value\" id=\"valStreamArch\">-</span>\n        </div>\n      </div>\n\n      <div class=\"filter-group\" id=\"filterContainer\">\n        <!-- Structural Filter Chips injected via JS -->\n      </div>\n    </div>\n\n    <!-- Structural Timeline Bar -->\n    <div class=\"timeline-container\">\n      <div class=\"timeline-header\">\n        <span>0x00000000 (0B)</span>\n        <span id=\"timelineMidOffset\">STRUCTURAL BYTE MAP</span>\n        <span id=\"timelineEndOffset\">EOF</span>\n      </div>\n      <div class=\"timeline-bar\" id=\"timelineBar\"></div>\n    </div>\n\n    <!-- Workspace Grid -->\n    <div class=\"workspace-grid\">\n      <!-- Hex Viewer Pane -->\n      <div class=\"hex-pane\">\n        <div class=\"pane-header\">\n          <span>HEXADECIMAL DENSE BYTE STREAM</span>\n          <input type=\"text\" class=\"search-input\" id=\"searchOffset\" placeholder=\"Seek offset (e.g. 0x100)\" onkeydown=\"if(event.key==='Enter') seekOffset(this.value)\">\n        </div>\n        <div class=\"hex-table-wrapper\" id=\"hexContainer\">\n          <div class=\"empty-state\">Load a local binary or select a preloaded sample to begin inspection.</div>\n        </div>\n      </div>\n\n      <!-- Inspector Sidebar -->\n      <div class=\"inspector-pane\">\n        <div class=\"inspector-title\">SEGMENT DIAGNOSTICS</div>\n        <div id=\"inspectorContent\">\n          <div class=\"empty-state\">Select a segment or byte offset to view calibrated confidence and diagnostics.</div>\n        </div>\n      </div>\n    </div>\n  </main>\n\n  <script>\n    // Global State\n    let currentData = null;\n    let currentResult = null;\n    let selectedSegmentIndex = 0;\n    let activeFilter = null;\n\n    const CATEGORY_COLORS = {\n      CODE: \"#00F0FF\",\n      DATA_STRING: \"#F59E0B\",\n      DATA_TABLE: \"#10B981\",\n      DATA_RAW: \"#3B82F6\",\n      PADDING: \"#64748B\",\n      COMPRESSED_OPAQUE: \"#8B5CF6\",\n      UNKNOWN_AMBIGUOUS: \"#EF4444\"\n    };\n\n    // Initialize Filter Chips\n    const filterContainer = document.getElementById(\"filterContainer\");\n    Object.entries(CATEGORY_COLORS).forEach(([cat, col]) => {\n      const chip = document.createElement(\"div\");\n      chip.className = \"chip\";\n      chip.style.color = col;\n      chip.style.backgroundColor = col + \"22\";\n      chip.innerHTML = `<span style=\"width:8px;height:8px;border-radius:50%;background:${col}\"></span> ${cat}`;\n      chip.onclick = () => toggleFilter(cat, chip);\n      filterContainer.appendChild(chip);\n    });\n\n    function toggleFilter(cat, chip) {\n      if (activeFilter === cat) {\n        activeFilter = null;\n        chip.classList.remove(\"active\");\n      } else {\n        document.querySelectorAll(\".chip\").forEach(c => c.classList.remove(\"active\"));\n        activeFilter = cat;\n        chip.classList.add(\"active\");\n      }\n      renderTimeline();\n    }\n\n    // File Input Listener\n    document.getElementById(\"fileInput\").addEventListener(\"change\", function(e) {\n      const file = e.target.files[0];\n      if (!file) return;\n\n      const reader = new FileReader();\n      reader.onload = function(evt) {\n        currentData = new Uint8Array(evt.target.result);\n        analyzeClientSide(file.name, currentData);\n      };\n      reader.readAsArrayBuffer(file);\n    });\n\n    // Client-Side Structural Analyzer\n    function analyzeClientSide(name, bytes) {\n      const totalLen = bytes.length;\n      document.getElementById(\"valStreamName\").innerText = name;\n      document.getElementById(\"valStreamSize\").innerText = totalLen.toLocaleString() + \" bytes\";\n\n      // Lightweight heuristic & pattern segmentation\n      const segments = [];\n      const windowSize = 64;\n      const step = 32;\n\n      const frameCats = [];\n      for (let off = 0; off < totalLen; off += step) {\n        const end = Math.min(off + windowSize, totalLen);\n        const chunk = bytes.subarray(off, end);\n        const diag = calcDiagnostics(chunk);\n\n        let cat = \"DATA_RAW\";\n        let arch = \"NONE\";\n\n        if (diag.nullRatio >= 0.80 || (diag.entropy < 0.5 && diag.nullRatio > 0.4)) {\n          cat = \"PADDING\";\n        } else if (diag.printableRatio >= 0.70) {\n          cat = \"DATA_STRING\";\n        } else if (diag.entropy >= 7.2) {\n          cat = \"COMPRESSED_OPAQUE\";\n        } else if (diag.nullRatio >= 0.25 && diag.entropy <= 4.2) {\n          cat = \"DATA_TABLE\";\n        } else if (diag.entropy >= 5.0 && diag.entropy <= 6.8 && diag.printableRatio < 0.40) {\n          cat = \"CODE\";\n          arch = \"x86_64\";\n        }\n\n        frameCats.push({ start: off, end: end, cat: cat, arch: arch, conf: 0.85, diag: diag });\n      }\n\n      // Coalesce dense frames\n      let segStart = 0;\n      let currCat = frameCats.length > 0 ? frameCats[0].cat : \"DATA_RAW\";\n      let currArch = frameCats.length > 0 ? frameCats[0].arch : \"NONE\";\n\n      for (let i = 1; i < frameCats.length; i++) {\n        if (frameCats[i].cat !== currCat || frameCats[i].arch !== currArch) {\n          const cut = frameCats[i].start;\n          const chunk = bytes.subarray(segStart, cut);\n          segments.push({\n            start: segStart,\n            end: cut,\n            length: cut - segStart,\n            category: currCat,\n            arch: currArch,\n            confidence: 0.92,\n            diagnostics: calcDiagnostics(chunk)\n          });\n          segStart = cut;\n          currCat = frameCats[i].cat;\n          currArch = frameCats[i].arch;\n        }\n      }\n\n      if (segStart < totalLen) {\n        const chunk = bytes.subarray(segStart, totalLen);\n        segments.push({\n          start: segStart,\n          end: totalLen,\n          length: totalLen - segStart,\n          category: currCat,\n          arch: currArch,\n          confidence: 0.92,\n          diagnostics: calcDiagnostics(chunk)\n        });\n      }\n\n      currentResult = {\n        stream_id: name,\n        total_bytes: totalLen,\n        segments: segments\n      };\n\n      document.getElementById(\"valSegmentCount\").innerText = segments.length;\n      document.getElementById(\"timelineEndOffset\").innerText = \"0x\" + totalLen.toString(16).toUpperCase();\n\n      renderTimeline();\n      selectSegment(0);\n    }\n\n    function calcDiagnostics(bytes) {\n      if (bytes.length === 0) return { entropy: 0, nullRatio: 0, printableRatio: 0 };\n      const counts = new Uint32Array(256);\n      let nulls = 0;\n      let printable = 0;\n\n      for (let i = 0; i < bytes.length; i++) {\n        const b = bytes[i];\n        counts[b]++;\n        if (b === 0) nulls++;\n        else if (b >= 0x20 && b <= 0x7E) printable++;\n      }\n\n      let entropy = 0;\n      const len = bytes.length;\n      for (let i = 0; i < 256; i++) {\n        if (counts[i] > 0) {\n          const p = counts[i] / len;\n          entropy -= p * Math.log2(p);\n        }\n      }\n\n      return {\n        entropy: Math.round(entropy * 100) / 100,\n        nullRatio: Math.round((nulls / len) * 100) / 100,\n        printableRatio: Math.round((printable / len) * 100) / 100\n      };\n    }\n\n    // Render Timeline\n    function renderTimeline() {\n      const bar = document.getElementById(\"timelineBar\");\n      bar.innerHTML = \"\";\n      if (!currentResult || !currentResult.segments.length) return;\n\n      const total = currentResult.total_bytes;\n      currentResult.segments.forEach((seg, idx) => {\n        const segWidth = ((seg.end - seg.start) / total) * 100;\n        const div = document.createElement(\"div\");\n        div.className = \"timeline-segment\" + (idx === selectedSegmentIndex ? \" selected\" : \"\");\n        div.style.width = segWidth + \"%\";\n        div.style.backgroundColor = CATEGORY_COLORS[seg.category] || \"#64748B\";\n\n        if (activeFilter && seg.category !== activeFilter) {\n          div.style.opacity = \"0.15\";\n        }\n\n        div.title = `[0x${seg.start.toString(16)} - 0x${seg.end.toString(16)}) ${seg.category} (${seg.length}B)`;\n        div.onclick = () => selectSegment(idx);\n        bar.appendChild(div);\n      });\n    }\n\n    // Select Segment & Update Inspector / Hex\n    function selectSegment(idx) {\n      if (!currentResult || idx < 0 || idx >= currentResult.segments.length) return;\n      selectedSegmentIndex = idx;\n      renderTimeline();\n\n      const seg = currentResult.segments[idx];\n      renderInspector(seg);\n      renderHexView(seg.start, 512);\n    }\n\n    function renderInspector(seg) {\n      const container = document.getElementById(\"inspectorContent\");\n      const col = CATEGORY_COLORS[seg.category] || \"#FFF\";\n\n      container.innerHTML = `\n        <div style=\"display:flex;align-items:center;gap:10px;\">\n          <span style=\"width:14px;height:14px;border-radius:3px;background:${col}\"></span>\n          <span style=\"font-size:16px;font-weight:700;color:${col}\">${seg.category}</span>\n        </div>\n\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Start Offset</span>\n          <span class=\"prop-value\">0x${seg.start.toString(16).toUpperCase().padStart(8, '0')} (${seg.start.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">End Offset</span>\n          <span class=\"prop-value\">0x${seg.end.toString(16).toUpperCase().padStart(8, '0')} (${seg.end.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Segment Length</span>\n          <span class=\"prop-value\">${seg.length.toLocaleString()} bytes</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Target ISA</span>\n          <span class=\"prop-value\" style=\"color:var(--color-code)\">${seg.arch}</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Confidence</span>\n          <span class=\"prop-value\">${(seg.confidence * 100).toFixed(1)}%</span>\n        </div>\n        <div class=\"confidence-meter\">\n          <div class=\"confidence-fill\" style=\"width:${seg.confidence * 100}%;background:${col}\"></div>\n        </div>\n\n        <div class=\"entropy-card\">\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Shannon Entropy</span>\n            <span class=\"prop-value\">${seg.diagnostics.entropy} bits/byte</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Printable ASCII Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.printableRatio * 100).toFixed(0)}%</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Null Byte Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.nullRatio * 100).toFixed(0)}%</span>\n          </div>\n        </div>\n      `;\n    }\n\n    function renderHexView(startOffset, length) {\n      const container = document.getElementById(\"hexContainer\");\n      if (!currentData) return;\n\n      const endOffset = Math.min(currentData.length, startOffset + length);\n      let html = \"\";\n\n      for (let row = startOffset; row < endOffset; row += 16) {\n        const rowEnd = Math.min(endOffset, row + 16);\n        const hexParts = [];\n        let asciiStr = \"\";\n\n        for (let i = row; i < rowEnd; i++) {\n          const b = currentData[i];\n          hexParts.push(b.toString(16).toUpperCase().padStart(2, '0'));\n          asciiStr += (b >= 0x20 && b <= 0x7E) ? String.fromCharCode(b) : \".\";\n        }\n\n        while (hexParts.length < 16) hexParts.push(\"  \");\n        while (asciiStr.length < 16) asciiStr += \" \";\n\n        const leftHex = hexParts.slice(0, 8).join(\" \");\n        const rightHex = hexParts.slice(8, 16).join(\" \");\n        const offStr = row.toString(16).toUpperCase().padStart(8, '0');\n\n        html += `\n          <div class=\"hex-row\">\n            <span class=\"hex-offset\">${offStr}</span>\n            <span class=\"hex-bytes\">${leftHex}&nbsp;&nbsp;${rightHex}</span>\n            <span class=\"hex-ascii\">${escapeHtml(asciiStr)}</span>\n          </div>\n        `;\n      }\n\n      container.innerHTML = html;\n    }\n\n    function escapeHtml(str) {\n      return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n    }\n\n    function seekOffset(query) {\n      if (!currentData) return;\n      let off = query.startsWith(\"0x\") || query.startsWith(\"0X\") ? parseInt(query, 16) : parseInt(query, 10);\n      if (isNaN(off) || off < 0 || off >= currentData.length) {\n        alert(\"Invalid byte offset.\");\n        return;\n      }\n\n      // Find enclosing segment\n      if (currentResult) {\n        const segIdx = currentResult.segments.findIndex(s => off >= s.start && off < s.end);\n        if (segIdx !== -1) selectSegment(segIdx);\n      }\n      renderHexView(off, 512);\n    }\n\n    function loadSample(type) {\n      const sampleSize = 8192;\n      const buf = new Uint8Array(sampleSize);\n\n      if (type === 'mixed') {\n        // Synthesize mixed ARM/x86/strings/tables\n        // 0..2048: x86 code\n        for (let i = 0; i < 2048; i++) buf[i] = (i % 7 === 0) ? 0x55 : (i % 5 === 0) ? 0x48 : (i * 31) % 256;\n        // 2048..2064: padding nulls\n        for (let i = 2048; i < 2064; i++) buf[i] = 0x00;\n        // 2064..3500: ASCII strings\n        const text = \"KETHRAVAX_REVERSE_ENGINEERING_CORE_STREAM_IDENTIFIER_0x00_FATAL_ERROR_INITIALIZING_DMA\\x00\";\n        for (let i = 2064; i < 3500; i++) buf[i] = text.charCodeAt((i - 2064) % text.length);\n        // 3500..5500: high entropy\n        for (let i = 3500; i < 5500; i++) buf[i] = Math.floor(Math.random() * 256);\n        // 5500..sampleSize: pointer table\n        for (let i = 5500; i < sampleSize; i += 4) {\n          buf[i] = (i & 0xFF);\n          buf[i+1] = 0x10;\n          buf[i+2] = 0x40;\n          buf[i+3] = 0x00;\n        }\n        currentData = buf;\n        analyzeClientSide(\"synthetic_mixed_payload.bin\", buf);\n      } else {\n        // x86-64 binary sample\n        for (let i = 0; i < 4096; i++) buf[i] = (i % 9 === 0) ? 0x55 : (i % 4 === 0) ? 0x48 : (i * 17) % 256;\n        for (let i = 4096; i < 5000; i++) buf[i] = 0xCC; // int3 padding\n        for (let i = 5000; i < sampleSize; i++) buf[i] = \"API_INITIALIZE_KERNEL_HOOK\\x00\".charCodeAt((i - 5000) % 27);\n        currentData = buf;\n        analyzeClientSide(\"sample_x86_64.exe\", buf);\n      }\n    }\n\n    function exportJSON() {\n      if (!currentResult) {\n        alert(\"No analysis to export.\");\n        return;\n      }\n      const dataStr = \"data:text/json;charset=utf-8,\" + encodeURIComponent(JSON.stringify(currentResult, null, 2));\n      const downloadAnchor = document.createElement('a');\n      downloadAnchor.setAttribute(\"href\", dataStr);\n      downloadAnchor.setAttribute(\"download\", `${currentResult.stream_id}_segments.json`);\n      document.body.appendChild(downloadAnchor);\n      downloadAnchor.click();\n      downloadAnchor.remove();\n    }\n  </script>\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}, "/explorer/": {"body": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KETHRAVAX \u2014 Interactive Binary Explorer</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Fira+Code:wght@400;500;600&family=Inter:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg-base: #090D16;\n      --bg-surface: #111726;\n      --bg-card: #161F33;\n      --border-color: #232F4D;\n      --border-active: #384B78;\n      --text-main: #F8FAFC;\n      --text-muted: #94A3B8;\n      --text-dim: #64748B;\n      \n      --color-code: #00F0FF;\n      --color-string: #F59E0B;\n      --color-table: #10B981;\n      --color-raw: #3B82F6;\n      --color-padding: #64748B;\n      --color-opaque: #8B5CF6;\n      --color-unknown: #EF4444;\n      \n      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n      --font-mono: 'Fira Code', 'JetBrains Mono', monospace;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      background-color: var(--bg-base);\n      color: var(--text-main);\n      font-family: var(--font-sans);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      overflow-x: hidden;\n    }\n\n    header {\n      background: rgba(17, 23, 38, 0.85);\n      backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border-color);\n      padding: 12px 24px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      top: 0;\n      z-index: 100;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .brand-logo {\n      width: 32px;\n      height: 32px;\n      background: linear-gradient(135deg, var(--color-code), #6366F1);\n      border-radius: 6px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      color: #000;\n      font-size: 16px;\n    }\n    .brand-title {\n      font-weight: 700;\n      font-size: 18px;\n      letter-spacing: 0.05em;\n    }\n    .brand-badge {\n      font-size: 11px;\n      font-family: var(--font-mono);\n      background: rgba(0, 240, 255, 0.15);\n      color: var(--color-code);\n      padding: 2px 8px;\n      border-radius: 4px;\n      border: 1px solid rgba(0, 240, 255, 0.3);\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n    .btn {\n      background: var(--bg-card);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 8px 14px;\n      border-radius: 6px;\n      font-size: 13px;\n      font-weight: 500;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      transition: all 0.15s ease;\n    }\n    .btn:hover {\n      background: var(--border-active);\n      border-color: var(--color-code);\n    }\n    .btn-primary {\n      background: linear-gradient(135deg, #0284C7, #00F0FF);\n      color: #000;\n      font-weight: 600;\n      border: none;\n    }\n    .btn-primary:hover {\n      opacity: 0.9;\n    }\n\n    main {\n      flex: 1;\n      padding: 20px 24px;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n    }\n\n    .control-bar {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 14px 18px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n    .file-status {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n      font-size: 13px;\n    }\n    .status-item {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n    }\n    .status-label {\n      font-size: 11px;\n      color: var(--text-dim);\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n    }\n    .status-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .filter-group {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      flex-wrap: wrap;\n    }\n    .chip {\n      font-size: 12px;\n      padding: 4px 10px;\n      border-radius: 4px;\n      cursor: pointer;\n      user-select: none;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      border: 1px solid transparent;\n      transition: all 0.15s ease;\n    }\n    .chip.active {\n      border-color: currentColor;\n    }\n\n    /* Structural Timeline Minimap */\n    .timeline-container {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n    }\n    .timeline-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 8px;\n      font-size: 12px;\n      color: var(--text-muted);\n      font-family: var(--font-mono);\n    }\n    .timeline-bar {\n      height: 28px;\n      background: #0D121F;\n      border-radius: 4px;\n      overflow: hidden;\n      display: flex;\n      position: relative;\n      cursor: pointer;\n      border: 1px solid var(--border-color);\n    }\n    .timeline-segment {\n      height: 100%;\n      position: relative;\n      transition: opacity 0.15s;\n    }\n    .timeline-segment:hover {\n      filter: brightness(1.25);\n    }\n    .timeline-segment.selected {\n      outline: 2px solid #FFF;\n      z-index: 2;\n    }\n\n    /* Workspace Grid: Hex View + Inspector */\n    .workspace-grid {\n      display: grid;\n      grid-template-columns: 1fr 380px;\n      gap: 20px;\n      flex: 1;\n    }\n\n    /* Hex View */\n    .hex-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n      height: 540px;\n    }\n    .pane-header {\n      background: var(--bg-card);\n      border-bottom: 1px solid var(--border-color);\n      padding: 10px 16px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      font-size: 13px;\n      font-weight: 600;\n    }\n    .search-input {\n      background: var(--bg-base);\n      border: 1px solid var(--border-color);\n      color: var(--text-main);\n      padding: 4px 10px;\n      border-radius: 4px;\n      font-family: var(--font-mono);\n      font-size: 12px;\n      width: 140px;\n    }\n    .search-input:focus {\n      outline: 1px solid var(--color-code);\n    }\n\n    .hex-table-wrapper {\n      flex: 1;\n      overflow-y: auto;\n      padding: 8px 16px;\n      font-family: var(--font-mono);\n      font-size: 13px;\n      line-height: 1.6;\n    }\n    .hex-row {\n      display: flex;\n      gap: 16px;\n      padding: 1px 0;\n      border-radius: 2px;\n    }\n    .hex-row:hover {\n      background: rgba(255, 255, 255, 0.03);\n    }\n    .hex-offset {\n      color: var(--text-dim);\n      user-select: none;\n      width: 80px;\n    }\n    .hex-bytes {\n      display: flex;\n      gap: 8px;\n      width: 380px;\n    }\n    .hex-byte {\n      display: inline-block;\n      width: 20px;\n      text-align: center;\n      cursor: pointer;\n      border-radius: 2px;\n    }\n    .hex-byte:hover {\n      background: #FFF;\n      color: #000;\n    }\n    .hex-ascii {\n      color: var(--text-muted);\n      letter-spacing: 0.1em;\n      white-space: pre;\n    }\n\n    /* Inspector Sidebar */\n    .inspector-pane {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-color);\n      border-radius: 8px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n      overflow-y: auto;\n      max-height: 540px;\n    }\n    .inspector-title {\n      font-size: 14px;\n      font-weight: 600;\n      border-bottom: 1px solid var(--border-color);\n      padding-bottom: 8px;\n    }\n    .prop-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 13px;\n      padding: 6px 0;\n      border-bottom: 1px dashed rgba(255,255,255,0.05);\n    }\n    .prop-name {\n      color: var(--text-muted);\n    }\n    .prop-value {\n      font-family: var(--font-mono);\n      font-weight: 600;\n      color: var(--text-main);\n    }\n\n    .confidence-meter {\n      height: 8px;\n      background: #000;\n      border-radius: 4px;\n      overflow: hidden;\n      margin-top: 4px;\n    }\n    .confidence-fill {\n      height: 100%;\n      background: var(--color-code);\n      width: 0%;\n      transition: width 0.3s ease;\n    }\n\n    .entropy-card {\n      background: var(--bg-card);\n      border-radius: 6px;\n      padding: 12px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .empty-state {\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      height: 100%;\n      color: var(--text-dim);\n      gap: 12px;\n      font-size: 14px;\n    }\n\n    input[type=\"file\"] {\n      display: none;\n    }\n  </style>\n</head>\n<body>\n\n  <header>\n    <div class=\"brand\">\n      <div class=\"brand-logo\">K</div>\n      <div>\n        <span class=\"brand-title\">KETHRAVAX</span>\n        <span class=\"brand-badge\">BINARY EXPLORER</span>\n      </div>\n    </div>\n\n    <div class=\"header-actions\">\n      <input type=\"file\" id=\"fileInput\">\n      <button class=\"btn\" onclick=\"document.getElementById('fileInput').click()\">\n        \ud83d\udcc1 Open Local Binary\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('mixed')\">\n        \u26a1 Load Mixed Stream Sample\n      </button>\n      <button class=\"btn\" onclick=\"loadSample('x86')\">\n        \ud83d\udd2c Load x86-64 Sample\n      </button>\n      <button class=\"btn\" onclick=\"exportJSON()\">\n        \ud83d\udcbe Export JSON\n      </button>\n    </div>\n  </header>\n\n  <main>\n    <!-- Control Bar -->\n    <div class=\"control-bar\">\n      <div class=\"file-status\">\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Target</span>\n          <span class=\"status-value\" id=\"valStreamName\">No file loaded</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Stream Size</span>\n          <span class=\"status-value\" id=\"valStreamSize\">0 bytes</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Segments Detected</span>\n          <span class=\"status-value\" id=\"valSegmentCount\">0</span>\n        </div>\n        <div class=\"status-item\">\n          <span class=\"status-label\">Active Architecture</span>\n          <span class=\"status-value\" id=\"valStreamArch\">-</span>\n        </div>\n      </div>\n\n      <div class=\"filter-group\" id=\"filterContainer\">\n        <!-- Structural Filter Chips injected via JS -->\n      </div>\n    </div>\n\n    <!-- Structural Timeline Bar -->\n    <div class=\"timeline-container\">\n      <div class=\"timeline-header\">\n        <span>0x00000000 (0B)</span>\n        <span id=\"timelineMidOffset\">STRUCTURAL BYTE MAP</span>\n        <span id=\"timelineEndOffset\">EOF</span>\n      </div>\n      <div class=\"timeline-bar\" id=\"timelineBar\"></div>\n    </div>\n\n    <!-- Workspace Grid -->\n    <div class=\"workspace-grid\">\n      <!-- Hex Viewer Pane -->\n      <div class=\"hex-pane\">\n        <div class=\"pane-header\">\n          <span>HEXADECIMAL DENSE BYTE STREAM</span>\n          <input type=\"text\" class=\"search-input\" id=\"searchOffset\" placeholder=\"Seek offset (e.g. 0x100)\" onkeydown=\"if(event.key==='Enter') seekOffset(this.value)\">\n        </div>\n        <div class=\"hex-table-wrapper\" id=\"hexContainer\">\n          <div class=\"empty-state\">Load a local binary or select a preloaded sample to begin inspection.</div>\n        </div>\n      </div>\n\n      <!-- Inspector Sidebar -->\n      <div class=\"inspector-pane\">\n        <div class=\"inspector-title\">SEGMENT DIAGNOSTICS</div>\n        <div id=\"inspectorContent\">\n          <div class=\"empty-state\">Select a segment or byte offset to view calibrated confidence and diagnostics.</div>\n        </div>\n      </div>\n    </div>\n  </main>\n\n  <script>\n    // Global State\n    let currentData = null;\n    let currentResult = null;\n    let selectedSegmentIndex = 0;\n    let activeFilter = null;\n\n    const CATEGORY_COLORS = {\n      CODE: \"#00F0FF\",\n      DATA_STRING: \"#F59E0B\",\n      DATA_TABLE: \"#10B981\",\n      DATA_RAW: \"#3B82F6\",\n      PADDING: \"#64748B\",\n      COMPRESSED_OPAQUE: \"#8B5CF6\",\n      UNKNOWN_AMBIGUOUS: \"#EF4444\"\n    };\n\n    // Initialize Filter Chips\n    const filterContainer = document.getElementById(\"filterContainer\");\n    Object.entries(CATEGORY_COLORS).forEach(([cat, col]) => {\n      const chip = document.createElement(\"div\");\n      chip.className = \"chip\";\n      chip.style.color = col;\n      chip.style.backgroundColor = col + \"22\";\n      chip.innerHTML = `<span style=\"width:8px;height:8px;border-radius:50%;background:${col}\"></span> ${cat}`;\n      chip.onclick = () => toggleFilter(cat, chip);\n      filterContainer.appendChild(chip);\n    });\n\n    function toggleFilter(cat, chip) {\n      if (activeFilter === cat) {\n        activeFilter = null;\n        chip.classList.remove(\"active\");\n      } else {\n        document.querySelectorAll(\".chip\").forEach(c => c.classList.remove(\"active\"));\n        activeFilter = cat;\n        chip.classList.add(\"active\");\n      }\n      renderTimeline();\n    }\n\n    // File Input Listener\n    document.getElementById(\"fileInput\").addEventListener(\"change\", function(e) {\n      const file = e.target.files[0];\n      if (!file) return;\n\n      const reader = new FileReader();\n      reader.onload = function(evt) {\n        currentData = new Uint8Array(evt.target.result);\n        analyzeClientSide(file.name, currentData);\n      };\n      reader.readAsArrayBuffer(file);\n    });\n\n    // Client-Side Structural Analyzer\n    function analyzeClientSide(name, bytes) {\n      const totalLen = bytes.length;\n      document.getElementById(\"valStreamName\").innerText = name;\n      document.getElementById(\"valStreamSize\").innerText = totalLen.toLocaleString() + \" bytes\";\n\n      // Lightweight heuristic & pattern segmentation\n      const segments = [];\n      const windowSize = 64;\n      const step = 32;\n\n      const frameCats = [];\n      for (let off = 0; off < totalLen; off += step) {\n        const end = Math.min(off + windowSize, totalLen);\n        const chunk = bytes.subarray(off, end);\n        const diag = calcDiagnostics(chunk);\n\n        let cat = \"DATA_RAW\";\n        let arch = \"NONE\";\n\n        if (diag.nullRatio >= 0.80 || (diag.entropy < 0.5 && diag.nullRatio > 0.4)) {\n          cat = \"PADDING\";\n        } else if (diag.printableRatio >= 0.70) {\n          cat = \"DATA_STRING\";\n        } else if (diag.entropy >= 7.2) {\n          cat = \"COMPRESSED_OPAQUE\";\n        } else if (diag.nullRatio >= 0.25 && diag.entropy <= 4.2) {\n          cat = \"DATA_TABLE\";\n        } else if (diag.entropy >= 5.0 && diag.entropy <= 6.8 && diag.printableRatio < 0.40) {\n          cat = \"CODE\";\n          arch = \"x86_64\";\n        }\n\n        frameCats.push({ start: off, end: end, cat: cat, arch: arch, conf: 0.85, diag: diag });\n      }\n\n      // Coalesce dense frames\n      let segStart = 0;\n      let currCat = frameCats.length > 0 ? frameCats[0].cat : \"DATA_RAW\";\n      let currArch = frameCats.length > 0 ? frameCats[0].arch : \"NONE\";\n\n      for (let i = 1; i < frameCats.length; i++) {\n        if (frameCats[i].cat !== currCat || frameCats[i].arch !== currArch) {\n          const cut = frameCats[i].start;\n          const chunk = bytes.subarray(segStart, cut);\n          segments.push({\n            start: segStart,\n            end: cut,\n            length: cut - segStart,\n            category: currCat,\n            arch: currArch,\n            confidence: 0.92,\n            diagnostics: calcDiagnostics(chunk)\n          });\n          segStart = cut;\n          currCat = frameCats[i].cat;\n          currArch = frameCats[i].arch;\n        }\n      }\n\n      if (segStart < totalLen) {\n        const chunk = bytes.subarray(segStart, totalLen);\n        segments.push({\n          start: segStart,\n          end: totalLen,\n          length: totalLen - segStart,\n          category: currCat,\n          arch: currArch,\n          confidence: 0.92,\n          diagnostics: calcDiagnostics(chunk)\n        });\n      }\n\n      currentResult = {\n        stream_id: name,\n        total_bytes: totalLen,\n        segments: segments\n      };\n\n      document.getElementById(\"valSegmentCount\").innerText = segments.length;\n      document.getElementById(\"timelineEndOffset\").innerText = \"0x\" + totalLen.toString(16).toUpperCase();\n\n      renderTimeline();\n      selectSegment(0);\n    }\n\n    function calcDiagnostics(bytes) {\n      if (bytes.length === 0) return { entropy: 0, nullRatio: 0, printableRatio: 0 };\n      const counts = new Uint32Array(256);\n      let nulls = 0;\n      let printable = 0;\n\n      for (let i = 0; i < bytes.length; i++) {\n        const b = bytes[i];\n        counts[b]++;\n        if (b === 0) nulls++;\n        else if (b >= 0x20 && b <= 0x7E) printable++;\n      }\n\n      let entropy = 0;\n      const len = bytes.length;\n      for (let i = 0; i < 256; i++) {\n        if (counts[i] > 0) {\n          const p = counts[i] / len;\n          entropy -= p * Math.log2(p);\n        }\n      }\n\n      return {\n        entropy: Math.round(entropy * 100) / 100,\n        nullRatio: Math.round((nulls / len) * 100) / 100,\n        printableRatio: Math.round((printable / len) * 100) / 100\n      };\n    }\n\n    // Render Timeline\n    function renderTimeline() {\n      const bar = document.getElementById(\"timelineBar\");\n      bar.innerHTML = \"\";\n      if (!currentResult || !currentResult.segments.length) return;\n\n      const total = currentResult.total_bytes;\n      currentResult.segments.forEach((seg, idx) => {\n        const segWidth = ((seg.end - seg.start) / total) * 100;\n        const div = document.createElement(\"div\");\n        div.className = \"timeline-segment\" + (idx === selectedSegmentIndex ? \" selected\" : \"\");\n        div.style.width = segWidth + \"%\";\n        div.style.backgroundColor = CATEGORY_COLORS[seg.category] || \"#64748B\";\n\n        if (activeFilter && seg.category !== activeFilter) {\n          div.style.opacity = \"0.15\";\n        }\n\n        div.title = `[0x${seg.start.toString(16)} - 0x${seg.end.toString(16)}) ${seg.category} (${seg.length}B)`;\n        div.onclick = () => selectSegment(idx);\n        bar.appendChild(div);\n      });\n    }\n\n    // Select Segment & Update Inspector / Hex\n    function selectSegment(idx) {\n      if (!currentResult || idx < 0 || idx >= currentResult.segments.length) return;\n      selectedSegmentIndex = idx;\n      renderTimeline();\n\n      const seg = currentResult.segments[idx];\n      renderInspector(seg);\n      renderHexView(seg.start, 512);\n    }\n\n    function renderInspector(seg) {\n      const container = document.getElementById(\"inspectorContent\");\n      const col = CATEGORY_COLORS[seg.category] || \"#FFF\";\n\n      container.innerHTML = `\n        <div style=\"display:flex;align-items:center;gap:10px;\">\n          <span style=\"width:14px;height:14px;border-radius:3px;background:${col}\"></span>\n          <span style=\"font-size:16px;font-weight:700;color:${col}\">${seg.category}</span>\n        </div>\n\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Start Offset</span>\n          <span class=\"prop-value\">0x${seg.start.toString(16).toUpperCase().padStart(8, '0')} (${seg.start.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">End Offset</span>\n          <span class=\"prop-value\">0x${seg.end.toString(16).toUpperCase().padStart(8, '0')} (${seg.end.toLocaleString()}B)</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Segment Length</span>\n          <span class=\"prop-value\">${seg.length.toLocaleString()} bytes</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Target ISA</span>\n          <span class=\"prop-value\" style=\"color:var(--color-code)\">${seg.arch}</span>\n        </div>\n        <div class=\"prop-row\">\n          <span class=\"prop-name\">Confidence</span>\n          <span class=\"prop-value\">${(seg.confidence * 100).toFixed(1)}%</span>\n        </div>\n        <div class=\"confidence-meter\">\n          <div class=\"confidence-fill\" style=\"width:${seg.confidence * 100}%;background:${col}\"></div>\n        </div>\n\n        <div class=\"entropy-card\">\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Shannon Entropy</span>\n            <span class=\"prop-value\">${seg.diagnostics.entropy} bits/byte</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Printable ASCII Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.printableRatio * 100).toFixed(0)}%</span>\n          </div>\n          <div class=\"prop-row\" style=\"border:none;\">\n            <span class=\"prop-name\">Null Byte Ratio</span>\n            <span class=\"prop-value\">${(seg.diagnostics.nullRatio * 100).toFixed(0)}%</span>\n          </div>\n        </div>\n      `;\n    }\n\n    function renderHexView(startOffset, length) {\n      const container = document.getElementById(\"hexContainer\");\n      if (!currentData) return;\n\n      const endOffset = Math.min(currentData.length, startOffset + length);\n      let html = \"\";\n\n      for (let row = startOffset; row < endOffset; row += 16) {\n        const rowEnd = Math.min(endOffset, row + 16);\n        const hexParts = [];\n        let asciiStr = \"\";\n\n        for (let i = row; i < rowEnd; i++) {\n          const b = currentData[i];\n          hexParts.push(b.toString(16).toUpperCase().padStart(2, '0'));\n          asciiStr += (b >= 0x20 && b <= 0x7E) ? String.fromCharCode(b) : \".\";\n        }\n\n        while (hexParts.length < 16) hexParts.push(\"  \");\n        while (asciiStr.length < 16) asciiStr += \" \";\n\n        const leftHex = hexParts.slice(0, 8).join(\" \");\n        const rightHex = hexParts.slice(8, 16).join(\" \");\n        const offStr = row.toString(16).toUpperCase().padStart(8, '0');\n\n        html += `\n          <div class=\"hex-row\">\n            <span class=\"hex-offset\">${offStr}</span>\n            <span class=\"hex-bytes\">${leftHex}&nbsp;&nbsp;${rightHex}</span>\n            <span class=\"hex-ascii\">${escapeHtml(asciiStr)}</span>\n          </div>\n        `;\n      }\n\n      container.innerHTML = html;\n    }\n\n    function escapeHtml(str) {\n      return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n    }\n\n    function seekOffset(query) {\n      if (!currentData) return;\n      let off = query.startsWith(\"0x\") || query.startsWith(\"0X\") ? parseInt(query, 16) : parseInt(query, 10);\n      if (isNaN(off) || off < 0 || off >= currentData.length) {\n        alert(\"Invalid byte offset.\");\n        return;\n      }\n\n      // Find enclosing segment\n      if (currentResult) {\n        const segIdx = currentResult.segments.findIndex(s => off >= s.start && off < s.end);\n        if (segIdx !== -1) selectSegment(segIdx);\n      }\n      renderHexView(off, 512);\n    }\n\n    function loadSample(type) {\n      const sampleSize = 8192;\n      const buf = new Uint8Array(sampleSize);\n\n      if (type === 'mixed') {\n        // Synthesize mixed ARM/x86/strings/tables\n        // 0..2048: x86 code\n        for (let i = 0; i < 2048; i++) buf[i] = (i % 7 === 0) ? 0x55 : (i % 5 === 0) ? 0x48 : (i * 31) % 256;\n        // 2048..2064: padding nulls\n        for (let i = 2048; i < 2064; i++) buf[i] = 0x00;\n        // 2064..3500: ASCII strings\n        const text = \"KETHRAVAX_REVERSE_ENGINEERING_CORE_STREAM_IDENTIFIER_0x00_FATAL_ERROR_INITIALIZING_DMA\\x00\";\n        for (let i = 2064; i < 3500; i++) buf[i] = text.charCodeAt((i - 2064) % text.length);\n        // 3500..5500: high entropy\n        for (let i = 3500; i < 5500; i++) buf[i] = Math.floor(Math.random() * 256);\n        // 5500..sampleSize: pointer table\n        for (let i = 5500; i < sampleSize; i += 4) {\n          buf[i] = (i & 0xFF);\n          buf[i+1] = 0x10;\n          buf[i+2] = 0x40;\n          buf[i+3] = 0x00;\n        }\n        currentData = buf;\n        analyzeClientSide(\"synthetic_mixed_payload.bin\", buf);\n      } else {\n        // x86-64 binary sample\n        for (let i = 0; i < 4096; i++) buf[i] = (i % 9 === 0) ? 0x55 : (i % 4 === 0) ? 0x48 : (i * 17) % 256;\n        for (let i = 4096; i < 5000; i++) buf[i] = 0xCC; // int3 padding\n        for (let i = 5000; i < sampleSize; i++) buf[i] = \"API_INITIALIZE_KERNEL_HOOK\\x00\".charCodeAt((i - 5000) % 27);\n        currentData = buf;\n        analyzeClientSide(\"sample_x86_64.exe\", buf);\n      }\n    }\n\n    function exportJSON() {\n      if (!currentResult) {\n        alert(\"No analysis to export.\");\n        return;\n      }\n      const dataStr = \"data:text/json;charset=utf-8,\" + encodeURIComponent(JSON.stringify(currentResult, null, 2));\n      const downloadAnchor = document.createElement('a');\n      downloadAnchor.setAttribute(\"href\", dataStr);\n      downloadAnchor.setAttribute(\"download\", `${currentResult.stream_id}_segments.json`);\n      document.body.appendChild(downloadAnchor);\n      downloadAnchor.click();\n      downloadAnchor.remove();\n    }\n  </script>\n</body>\n</html>\n\n", "type": "text/html; charset=utf-8"}};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    let pathname = url.pathname;

    if (pathname.endsWith('/') && pathname !== '/' && pathname !== '/explorer/') {
      pathname = pathname.slice(0, -1);
    }

    let asset = ASSETS[pathname];
    if (!asset && !pathname.includes('.')) {
      asset = ASSETS[pathname + '.html'] || ASSETS['/index.html'];
    }

    if (asset) {
      return new Response(asset.body, {
        headers: {
          "Content-Type": asset.type,
          "Cache-Control": "public, max-age=3600",
          "X-Content-Type-Options": "nosniff",
          "X-Frame-Options": "SAMEORIGIN",
          "Referrer-Policy": "strict-origin-when-cross-origin"
        }
      });
    }

    return new Response("404 Not Found — Kethravax", {
      status: 404,
      headers: { "Content-Type": "text/plain; charset=utf-8" }
    });
  }
};
